    pub fn closeConnectDatagramAssociation(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!void {
        try connect_datagram.validateStreamId(stream_id);
        if (!self.connect_datagrams.contains(stream_id)) return error.UnexpectedStream;
        self.connect_datagrams.unregister(stream_id);
    }

    pub fn sendResponse(self: *HandshakeServerSession, stream_id: u62, response: http3.Response) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        try self.sendResponseWithInformational(stream_id, &.{}, response);
    }

    pub fn sendResponseWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseWithDeadline(
            stream_id,
            response,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    pub fn sendResponseWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        return self.sendResponseWithInformationalAndDeadline(
            stream_id,
            &.{},
            response,
            deadline,
        );
    }

    /// Submit one complete static-QPACK response in one QUIC packet without
    /// waiting for pacing or reading UDP. HEADERS, optional DATA/trailers, and
    /// FIN commit transactionally, so an endpoint callback can retry after
    /// pacing, congestion, flow-control, or size rejection.
    pub fn trySendResponseLiteral(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
    ) Error!void {
        try self.requireEndpointCriticalStreamsReady();
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            server_response.automaticDate(
                self.options.auto_date_header,
                self.established.connection.endpoint.io,
                response,
            ),
            &response_headers_stack,
        );
        defer prepared.deinit(
            self.established.connection.endpoint.allocator,
        );
        _ = try trySendConnectionResponseLiteral(
            &self.established.connection,
            &self.stream_send_scratch,
            stream_id,
            prepared.value,
            self.control.settings.peer,
            true,
            0,
        );
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    /// Submit one static-QPACK response head without waiting for pacing or
    /// reading UDP. The encoded head must fit in one QUIC packet. A successful
    /// call retains body state for `trySendResponseBody` or
    /// `tryFinishResponseTrailers`; a failed call leaves it retryable.
    pub fn tryStartResponse(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        body_length: ?usize,
        trailers_pending: bool,
    ) Error!void {
        try self.requireEndpointCriticalStreamsReady();
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            server_response.automaticDate(
                self.options.auto_date_header,
                self.established.connection.endpoint.io,
                response,
            ),
            &response_headers_stack,
        );
        defer prepared.deinit(
            self.established.connection.endpoint.allocator,
        );
        const retained = try trySendConnectionStreamingResponseHeadLiteral(
            &self.established.connection,
            &self.stream_send_scratch,
            &self.outbound_bodies,
            stream_id,
            prepared.value,
            body_length,
            trailers_pending,
            self.options,
            self.control.settings.peer,
        );
        if (!retained) {
            finishServerRequest(
                &self.control,
                &self.request_lifecycle,
                stream_id,
            );
        }
    }

    /// Blocking aggregate-response helper for convenience serving loops. It
    /// sends the response body in bounded chunks and pumps ACK and MAX_*
    /// packets whenever body or trailer transmission exhausts peer credit.
    pub fn sendResponsePaced(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.sendResponsePacedUntil(
            stream_id,
            response,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponsePacedWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponsePacedWithDeadline(
            stream_id,
            response,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    pub fn sendResponsePacedWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendResponsePacedUntil(stream_id, response, deadline);
    }

    fn sendResponsePacedUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        try response.validateBodySemantics();
        if (deadline) |absolute| {
            _ = try deadline_policy.usableAwake(
                self.connectionIo(),
                absolute,
            );
        }
        while (true) {
            self.startResponseInternalUntil(
                stream_id,
                .{
                    .status = response.status,
                    .headers = response.headers,
                    .request_method = response.request_method,
                    .extended_connect = response.extended_connect,
                },
                response.body.len,
                response.trailers.len != 0,
                deadline,
            ) catch |err| switch (err) {
                error.FlowControlBlocked, error.CongestionLimited => {
                    if (self.established.connection.closed()) return err;
                    try self.receiveRequestPacketUntil(deadline);
                    continue;
                },
                else => |other| return other,
            };
            break;
        }
        // The aggregate API exposes no committed-byte cursor. Once HEADERS is
        // visible, a later DATA/trailer failure cannot be retried from the
        // original Response without duplicating the head or body prefix.
        errdefer self.established.connection.failClosedApplication(
            http3.ApplicationErrorCode.internal_error,
            "partial-http3-response",
        );
        if (!response.suppressesBody() and response.body.len != 0) {
            try self.sendResponseBodyPacedUntil(
                stream_id,
                response.body,
                response.trailers.len == 0,
                deadline,
            );
        }
        if (!response.suppressesBody() and response.trailers.len != 0) {
            try self.finishResponseTrailersPacedUntil(
                stream_id,
                response.trailers,
                deadline,
            );
        }
    }

    /// Send a parent response and one promised response while advancing both
    /// bodies under QUIC flow-control and congestion backpressure. Unlike the
    /// atomic compatibility helper below, this path never requires the whole
    /// pushed body to fit the peer's current connection or stream credit.
    pub fn sendResponseWithPushPaced(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
    ) Error!u62 {
        return self.sendResponseWithPushPacedUntil(
            request_stream_id,
            response,
            push,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponseWithPushPacedAndTimeout(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseWithPushPacedAndDeadline(
            request_stream_id,
            response,
            push,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Deadline-bounded aggregate server push. Once either response head is
    /// visible, non-cancellation failures close the connection because this
    /// convenience API does not expose separate parent/push byte cursors.
    pub fn sendResponseWithPushPacedAndDeadline(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendResponseWithPushPacedUntil(
            request_stream_id,
            response,
            push,
            deadline,
        );
    }

    fn sendResponseWithPushPacedUntil(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (deadline) |absolute| {
            _ = try deadline_policy.usableAwake(self.connectionIo(), absolute);
        }
        const push_stream_id = self.next_push_stream_id;
        if (deadline) |absolute| {
            try sendConnectionSettingsWithDeadline(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
                absolute,
            );
        } else {
            try sendConnectionSettings(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
            );
        }
        const max_push_id = self.control.peer_max_push_id orelse
            return error.PushIdExceeded;
        if (push.push_id > max_push_id) return error.PushIdExceeded;
        try validateNewServerPush(
            self.control,
            self.promised_push_ids,
            push.push_id,
        );
        try self.promised_push_ids.prepareInsertValue(
            self.established.connection.endpoint.allocator,
            push.push_id,
        );
        const next_push_stream_id = std.math.add(
            u62,
            push_stream_id,
            4,
        ) catch return error.StreamCreationError;

        const automatic_date = if (self.options.auto_date_header and
            (server_response.headerValue(response.headers, "date") == null or
                server_response.headerValue(push.response.headers, "date") == null))
            server_response.cachedDate(
                true,
                self.established.connection.endpoint.io,
            )
        else
            null;
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared_response = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            automatic_date,
            &response_headers_stack,
        );
        defer prepared_response.deinit(
            self.established.connection.endpoint.allocator,
        );
        var push_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared_push_response = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            push.response,
            automatic_date,
            &push_headers_stack,
        );
        defer prepared_push_response.deinit(
            self.established.connection.endpoint.allocator,
        );
        var prepared_push = push;
        prepared_push.response = prepared_push_response.value;

        var heads_committed = false;
        var clean_push_cancellation = false;
        errdefer if (heads_committed and
            !clean_push_cancellation)
        {
            self.established.connection.failClosedApplication(
                http3.ApplicationErrorCode.internal_error,
                "partial-http3-push",
            );
        };
        while (true) {
            if (deadline) |absolute| {
                sendConnectionPushStreamingHeadsWithDeadline(
                    &self.established.connection,
                    &self.push_send_scratch,
                    &self.critical_stream_send_scratch,
                    self.options,
                    self.control.settings.peer,
                    request_stream_id,
                    prepared_response.value,
                    push_stream_id,
                    prepared_push,
                    &self.qpack_encode,
                    &self.qpack_encoder_send,
                    &self.qpack_encoder_prefix_sent,
                    &self.outbound_bodies,
                    absolute,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        if (self.established.connection.closed()) {
                            return error.ConnectionClosed;
                        }
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    else => |other| return @errorCast(other),
                };
            } else {
                sendConnectionPushStreamingHeads(
                    &self.established.connection,
                    &self.push_send_scratch,
                    &self.critical_stream_send_scratch,
                    self.options,
                    self.control.settings.peer,
                    request_stream_id,
                    prepared_response.value,
                    push_stream_id,
                    prepared_push,
                    &self.qpack_encode,
                    &self.qpack_encoder_send,
                    &self.qpack_encoder_prefix_sent,
                    &self.outbound_bodies,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        if (self.established.connection.closed()) {
                            return error.ConnectionClosed;
                        }
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    else => |other| return @errorCast(other),
                };
            }
            break;
        }
        heads_committed = true;
        self.promised_push_ids.insertAssumeCapacity(push.push_id);
        self.next_push_stream_id = next_push_stream_id;

        var push_cancelled = false;
        if (self.outbound_bodies.find(push_stream_id) != null) {
            if (prepared_push.response.body.len != 0) {
                push_cancelled = try self.sendPushBodyPacedUntil(
                    push.push_id,
                    push_stream_id,
                    prepared_push.response.body,
                    prepared_push.response.trailers.len == 0,
                    deadline,
                );
            }
            if (!push_cancelled and prepared_push.response.trailers.len != 0) {
                push_cancelled = try self.finishPushTrailersPacedUntil(
                    push.push_id,
                    push_stream_id,
                    prepared_push.response.trailers,
                    deadline,
                );
            }
        } else {
            _ = try self.established.connection
                .requestCompletedLocalStreamRelease(push_stream_id);
        }
        if (self.outbound_bodies.find(request_stream_id) != null) {
            if (prepared_response.value.body.len != 0) {
                try self.sendResponseBodyPacedUntil(
                    request_stream_id,
                    prepared_response.value.body,
                    prepared_response.value.trailers.len == 0,
                    deadline,
                );
            }
            if (prepared_response.value.trailers.len != 0) {
                try self.finishResponseTrailersPacedUntil(
                    request_stream_id,
                    prepared_response.value.trailers,
                    deadline,
                );
            }
        } else {
            finishServerRequest(
                &self.control,
                &self.request_lifecycle,
                request_stream_id,
            );
        }
        self.control.retirePushPriority(
            self.established.connection.endpoint.allocator,
            push.push_id,
        );
        if (push_cancelled) {
            clean_push_cancellation = true;
            return error.RequestCancelled;
        }
        return push_stream_id;
    }

    fn sendPushBodyPacedUntil(
        self: *HandshakeServerSession,
        push_id: u64,
        push_stream_id: u62,
        data: []const u8,
        fin: bool,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!bool {
        const chunk_limit = pacedBodyChunkLimit(self.options);
        var offset: usize = 0;
        while (offset < data.len) {
            const end = @min(data.len, offset + chunk_limit);
            while (true) {
                if (self.control.pushCancelled(push_id) or
                    self.established.connection.streamStopped(
                        push_stream_id,
                    ) != null)
                {
                    try self.finishCancelledPacedPush(
                        push_id,
                        push_stream_id,
                        deadline,
                    );
                    return true;
                }
                if (deadline) |absolute| {
                    sendConnectionBodyChunkWithDeadline(
                        &self.established.connection,
                        &self.outbound_bodies,
                        push_stream_id,
                        data[offset..end],
                        fin and end == data.len,
                        self.options,
                        absolute,
                    ) catch |err| switch (err) {
                        error.FlowControlBlocked, error.CongestionLimited => {
                            try self.receiveRequestPacketUntil(deadline);
                            continue;
                        },
                        error.StreamStopped => {
                            try self.finishCancelledPacedPush(
                                push_id,
                                push_stream_id,
                                deadline,
                            );
                            return true;
                        },
                        else => |other| return @errorCast(other),
                    };
                } else {
                    sendConnectionBodyChunk(
                        &self.established.connection,
                        &self.outbound_bodies,
                        push_stream_id,
                        data[offset..end],
                        fin and end == data.len,
                        self.options,
                    ) catch |err| switch (err) {
                        error.FlowControlBlocked, error.CongestionLimited => {
                            try self.receiveRequestPacketUntil(deadline);
                            continue;
                        },
                        error.StreamStopped => {
                            try self.finishCancelledPacedPush(
                                push_id,
                                push_stream_id,
                                deadline,
                            );
                            return true;
                        },
                        else => |other| return @errorCast(other),
                    };
                }
                break;
            }
            offset = end;
        }
        if (fin) {
            _ = try self.established.connection
                .requestCompletedLocalStreamRelease(push_stream_id);
        }
        return false;
    }

    fn finishPushTrailersPacedUntil(
        self: *HandshakeServerSession,
        push_id: u64,
        push_stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!bool {
        while (true) {
            if (self.control.pushCancelled(push_id) or
                self.established.connection.streamStopped(push_stream_id) != null)
            {
                try self.finishCancelledPacedPush(
                    push_id,
                    push_stream_id,
                    deadline,
                );
                return true;
            }
            if (deadline) |absolute| {
                sendConnectionTrailersWithDeadline(
                    &self.established.connection,
                    &self.outbound_bodies,
                    &self.stream_send_scratch,
                    &self.critical_stream_send_scratch,
                    push_stream_id,
                    trailers,
                    self.control.settings.peer,
                    &self.qpack_encode,
                    &self.qpack_encoder_send,
                    &self.qpack_encoder_prefix_sent,
                    self.options,
                    absolute,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    error.StreamStopped => {
                        try self.finishCancelledPacedPush(
                            push_id,
                            push_stream_id,
                            deadline,
                        );
                        return true;
                    },
                    else => |other| return @errorCast(other),
                };
            } else {
                sendConnectionTrailers(
                    &self.established.connection,
                    &self.outbound_bodies,
                    &self.stream_send_scratch,
                    &self.critical_stream_send_scratch,
                    push_stream_id,
                    trailers,
                    self.control.settings.peer,
                    &self.qpack_encode,
                    &self.qpack_encoder_send,
                    &self.qpack_encoder_prefix_sent,
                    self.options,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    error.StreamStopped => {
                        try self.finishCancelledPacedPush(
                            push_id,
                            push_stream_id,
                            deadline,
                        );
                        return true;
                    },
                    else => |other| return @errorCast(other),
                };
            }
            _ = try self.established.connection
                .requestCompletedLocalStreamRelease(push_stream_id);
            return false;
        }
    }

    fn finishCancelledPacedPush(
        self: *HandshakeServerSession,
        push_id: u64,
        push_stream_id: u62,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        const application_error_code =
            if (self.established.connection.streamStopped(push_stream_id)) |stopped|
                stopped.application_error_code
            else
                http3.ApplicationErrorCode.request_cancelled;
        if (deadline) |absolute| {
            try self.established.connection.resetStreamWithDeadline(
                push_stream_id,
                application_error_code,
                absolute,
            );
        } else {
            try self.established.connection.resetStream(
                push_stream_id,
                application_error_code,
            );
        }
        self.qpack_encode.abandonStream(push_stream_id);
        _ = self.outbound_bodies.finish(push_stream_id);
        _ = try self.established.connection
            .requestCompletedLocalStreamRelease(push_stream_id);
        self.control.retirePushPriority(
            self.established.connection.endpoint.allocator,
            push_id,
        );
    }

    pub fn sendResponseWithPush(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
    ) Error!u62 {
        return self.sendResponseWithPushUntil(
            request_stream_id,
            response,
            push,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponseWithPushAndTimeout(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseWithPushAndDeadline(
            request_stream_id,
            response,
            push,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    pub fn sendResponseWithPushAndDeadline(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendResponseWithPushUntil(
            request_stream_id,
            response,
            push,
            deadline,
        );
    }

    fn sendResponseWithPushUntil(
        self: *HandshakeServerSession,
        request_stream_id: u62,
        response: http3.Response,
        push: ServerPush,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        const push_stream_id = self.next_push_stream_id;
        if (deadline) |absolute| {
            try sendConnectionSettingsWithDeadline(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
                absolute,
            );
        } else {
            try sendConnectionSettings(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
            );
        }
        const max_push_id = self.control.peer_max_push_id orelse
            return error.PushIdExceeded;
        if (push.push_id > max_push_id) return error.PushIdExceeded;
        try validateNewServerPush(
            self.control,
            self.promised_push_ids,
            push.push_id,
        );
        try self.promised_push_ids.prepareInsertValue(
            self.established.connection.endpoint.allocator,
            push.push_id,
        );
        const next_push_stream_id = std.math.add(
            u62,
            push_stream_id,
            4,
        ) catch return error.StreamCreationError;
        const automatic_date = if (self.options.auto_date_header and
            (server_response.headerValue(response.headers, "date") == null or
                server_response.headerValue(push.response.headers, "date") == null))
            server_response.cachedDate(
                true,
                self.established.connection.endpoint.io,
            )
        else
            null;
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared_response = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            automatic_date,
            &response_headers_stack,
        );
        defer prepared_response.deinit(
            self.established.connection.endpoint.allocator,
        );
        var push_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared_push_response = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            push.response,
            automatic_date,
            &push_headers_stack,
        );
        defer prepared_push_response.deinit(
            self.established.connection.endpoint.allocator,
        );
        var prepared_push = push;
        prepared_push.response = prepared_push_response.value;
        if (deadline) |absolute| {
            try sendConnectionPushWithDeadline(
                &self.established.connection,
                &self.push_send_scratch,
                &self.critical_stream_send_scratch,
                self.options,
                self.control.settings.peer,
                request_stream_id,
                prepared_response.value,
                push_stream_id,
                prepared_push,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                absolute,
            );
        } else {
            try sendConnectionPush(
                &self.established.connection,
                &self.push_send_scratch,
                &self.critical_stream_send_scratch,
                self.options,
                self.control.settings.peer,
                request_stream_id,
                prepared_response.value,
                push_stream_id,
                prepared_push,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
            );
        }
        _ = try self.established.connection
            .requestCompletedLocalStreamRelease(push_stream_id);
        self.promised_push_ids.insertAssumeCapacity(push.push_id);
        self.next_push_stream_id = next_push_stream_id;
        finishServerRequest(&self.control, &self.request_lifecycle, request_stream_id);
        self.control.retirePushPriority(
            self.established.connection.endpoint.allocator,
            push.push_id,
        );
        return push_stream_id;
    }

    pub fn startResponse(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        body_length: ?usize,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.startResponseInternalUntil(
            stream_id,
            response,
            body_length,
            false,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn startResponseWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        body_length: ?usize,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.startResponseWithDeadline(
            stream_id,
            response,
            body_length,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Send a streaming response head under one absolute deadline. The same
    /// budget covers SETTINGS/QPACK progress, pacing, and flow-control waits.
    pub fn startResponseWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        body_length: ?usize,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        while (true) {
            self.startResponseInternalUntil(
                stream_id,
                response,
                body_length,
                false,
                deadline,
            ) catch |err| switch (err) {
                error.FlowControlBlocked, error.CongestionLimited => {
                    if (self.established.connection.closed()) return err;
                    try self.receiveRequestPacketUntil(deadline);
                    continue;
                },
                else => |other| return other,
            };
            return;
        }
    }

    fn startResponseInternalUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        body_length: ?usize,
        trailers_pending: bool,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (deadline) |absolute| {
            try sendConnectionSettingsWithDeadline(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
                absolute,
            );
        } else {
            try sendConnectionSettings(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
            );
        }
        self.stream_send_scratch.reset();
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            server_response.automaticDate(
                self.options.auto_date_header,
                self.established.connection.endpoint.io,
                response,
            ),
            &response_headers_stack,
        );
        defer prepared.deinit(
            self.established.connection.endpoint.allocator,
        );
        const streaming = try prepared.value.writeStreamingHeadDynamic(
            &self.stream_send_scratch.encoded,
            self.established.connection.endpoint.allocator,
            self.control.settings.peer,
            stream_id,
            body_length,
            &self.qpack_encode,
        );
        errdefer self.qpack_encode.abandonStream(stream_id);
        if (deadline) |absolute| {
            try sendConnectionStreamingHeadWithDeadline(
                &self.established.connection,
                &self.stream_send_scratch,
                &self.critical_stream_send_scratch,
                stream_id,
                streaming.expected_length,
                streaming.body_allowed,
                trailers_pending,
                self.options,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.outbound_bodies,
                absolute,
            );
        } else {
            try sendConnectionStreamingHead(
                &self.established.connection,
                &self.stream_send_scratch,
                &self.critical_stream_send_scratch,
                stream_id,
                streaming.expected_length,
                streaming.body_allowed,
                trailers_pending,
                self.options,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.outbound_bodies,
            );
        }
        if (!streaming.body_allowed or
            (!trailers_pending and streaming.expected_length == 0))
        {
            finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
        }
    }

    fn tryStartResponseLiteral(
        self: *HandshakeServerSession,
        stream_id: u62,
        response: http3.Response,
        release_received: usize,
    ) Error!void {
        try self.requireEndpointCriticalStreamsReady();
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            server_response.automaticDate(
                self.options.auto_date_header,
                self.established.connection.endpoint.io,
                response,
            ),
            &response_headers_stack,
        );
        defer prepared.deinit(
            self.established.connection.endpoint.allocator,
        );
        if (prepared.value.suppressesBody()) {
            return error.InvalidContentLength;
        }
        try self.outbound_bodies.reserveOpen(stream_id);
        const next_offset = try trySendConnectionResponseLiteral(
            &self.established.connection,
            &self.stream_send_scratch,
            stream_id,
            prepared.value,
            self.control.settings.peer,
            false,
            release_received,
        );
        var body_send = quic.stream_state.SendState.init(stream_id);
        body_send.next_offset = next_offset;
        self.outbound_bodies.appendOpenAssumeCapacity(
            stream_id,
            body_send,
            null,
        );
    }

    fn requireEndpointCriticalStreamsReady(
        self: HandshakeServerSession,
    ) Error!void {
        if (!self.control.settings.sent or
            !self.qpack_encoder_prefix_sent or
            !self.qpack_decoder_prefix_sent)
        {
            return error.MissingSettings;
        }
    }

    pub fn sendResponseBody(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
            return responseResetError(cancel.application_error_code);
        }
        try sendConnectionBodyChunk(
            &self.established.connection,
            &self.outbound_bodies,
            stream_id,
            data,
            fin,
            self.options,
        );
        if (fin) finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    /// Submit one complete response DATA contribution in one QUIC packet,
    /// without waiting for pacing or reading the connection socket.
    pub fn trySendResponseBody(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
    ) Error!void {
        if (try self.finishPeerResponseCancellationOnce(stream_id)) |cancel| {
            return responseResetError(cancel.application_error_code);
        }
        try trySendConnectionBodyChunk(
            &self.established.connection,
            &self.outbound_bodies,
            stream_id,
            data,
            fin,
            self.options,
        );
        if (fin) {
            finishServerRequest(
                &self.control,
                &self.request_lifecycle,
                stream_id,
            );
        }
    }

    /// Submit several borrowed response slices as one DATA contribution and
    /// one QUIC packet without waiting or reading the shared endpoint socket.
    /// Failure is transactional for HTTP/3 body and QUIC stream state.
    pub fn trySendResponseBodyParts(
        self: *HandshakeServerSession,
        stream_id: u62,
        parts: []const []const u8,
        fin: bool,
    ) Error!void {
        if (try self.finishPeerResponseCancellationOnce(stream_id)) |cancel| {
            return responseResetError(cancel.application_error_code);
        }
        try trySendConnectionBodyParts(
            &self.established.connection,
            &self.outbound_bodies,
            stream_id,
            parts,
            fin,
            self.options,
        );
        if (fin) {
            finishServerRequest(
                &self.control,
                &self.request_lifecycle,
                stream_id,
            );
        }
    }

    /// Send response DATA while driving the receive side when QUIC
    /// backpressure says the peer must first ACK or extend flow-control
    /// credit.
    ///
    /// The plain `sendResponseBody` API intentionally exposes
    /// `CongestionLimited`/`FlowControlBlocked` for event-loop integrations
    /// that already own their writable scheduling. This helper is the blocking
    /// counterpart for simple runtimes and benchmarks: it processes
    /// request-side packets, preserving ACK/MAX_* progress, then retries the
    /// same small DATA chunk.
    pub fn sendResponseBodyPaced(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.sendResponseBodyPacedUntil(
            stream_id,
            data,
            fin,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponseBodyPacedWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
        progress: *BodyWriteProgress,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        progress.* = .{};
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseBodyPacedWithDeadline(
            stream_id,
            data,
            fin,
            progress,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Send one response DATA sequence under one absolute deadline. Progress
    /// reports the exact socket-visible application prefix and FIN state, so a
    /// caller can continue only the unsent suffix after a timeout.
    pub fn sendResponseBodyPacedWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
        progress: *BodyWriteProgress,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        progress.* = .{};
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        if (data.len == 0) {
            var committed_chunks: usize = 0;
            self.sendResponseBodyBatchPacedWithDeadline(
                &.{.{ .stream_id = stream_id, .data = data, .fin = fin }},
                &committed_chunks,
                deadline,
            ) catch |err| {
                progress.fin_committed = committed_chunks == 1 and fin;
                return err;
            };
            progress.fin_committed = fin;
            return;
        }
        const chunk_limit = pacedBodyChunkLimit(self.options);
        while (progress.committed_bytes < data.len) {
            const end = @min(
                data.len,
                progress.committed_bytes + chunk_limit,
            );
            const last = end == data.len;
            var committed_chunks: usize = 0;
            self.sendResponseBodyBatchPacedWithDeadline(
                &.{.{
                    .stream_id = stream_id,
                    .data = data[progress.committed_bytes..end],
                    .fin = fin and last,
                }},
                &committed_chunks,
                deadline,
            ) catch |err| {
                if (committed_chunks == 1) {
                    progress.committed_bytes = end;
                    progress.fin_committed = fin and last;
                }
                return err;
            };
            std.debug.assert(committed_chunks == 1);
            progress.committed_bytes = end;
            progress.fin_committed = fin and last;
        }
    }

    fn sendResponseBodyPacedUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (data.len == 0) {
            try self.sendResponseBodyPacedChunkUntil(
                stream_id,
                data,
                fin,
                deadline,
            );
            return;
        }
        const chunk_limit = pacedBodyChunkLimit(self.options);
        var offset: usize = 0;
        while (offset < data.len) {
            const end = @min(data.len, offset + chunk_limit);
            try self.sendResponseBodyPacedChunkUntil(
                stream_id,
                data[offset..end],
                fin and end == data.len,
                deadline,
            );
            offset = end;
        }
    }

    /// Send one logical Extended CONNECT byte sequence as packet-sized HTTP/3
    /// DATA contributions. Each contribution spans caller-slice boundaries
    /// when capacity permits, avoiding both a plaintext join and one transport
    /// submission per application slice. The cursor advances only after a
    /// successful send, retaining the normal paced retry behavior.
    pub fn sendResponseBodyPartsPaced(
        self: *HandshakeServerSession,
        stream_id: u62,
        parts: []const []const u8,
        fin: bool,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (self.options.max_frames_per_packet >= 2 and
            self.options.max_stream_frame_data != 0)
        {
            var cursor = BodyPartCursor{ .parts = parts };
            if (cursor.done()) {
                return self.sendResponseBodyPaced(stream_id, &.{}, fin);
            }
            var chunk_storage: [max_paced_body_part_descriptors][]const u8 = undefined;
            const chunk_limit = pacedBodyChunkLimit(self.options);
            var response_finished_by_fallback = false;
            while (!cursor.done()) {
                var attempt_limit = chunk_limit;
                while (true) {
                    var staged = cursor;
                    const chunk = staged.next(
                        &chunk_storage,
                        attempt_limit,
                        self.options.max_stream_frame_data,
                    );
                    const last = staged.done();
                    if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
                        return responseResetError(cancel.application_error_code);
                    }
                    sendConnectionBodyParts(
                        &self.established.connection,
                        &self.outbound_bodies,
                        stream_id,
                        chunk,
                        fin and last,
                        self.options,
                    ) catch |err| switch (err) {
                        error.FlowControlBlocked, error.CongestionLimited => {
                            try self.receiveRequestPacket();
                            continue;
                        },
                        error.DatagramTooLarge => {
                            if (attempt_limit == 1) {
                                try self.sendResponseBodyPaced(
                                    stream_id,
                                    chunk[0],
                                    fin and last,
                                );
                                response_finished_by_fallback = fin and last;
                                cursor = staged;
                                break;
                            }
                            attempt_limit = @max(@as(usize, 1), attempt_limit / 2);
                            continue;
                        },
                        else => return err,
                    };
                    cursor = staged;
                    break;
                }
            }
            if (fin and !response_finished_by_fallback) {
                finishServerRequest(
                    &self.control,
                    &self.request_lifecycle,
                    stream_id,
                );
            }
            return;
        }

        var non_empty: usize = 0;
        for (parts) |part| non_empty += @intFromBool(part.len != 0);
        if (non_empty == 0) {
            try self.sendResponseBodyPaced(stream_id, &.{}, fin);
            return;
        }
        var sent: usize = 0;
        for (parts) |part| {
            if (part.len == 0) continue;
            sent += 1;
            try self.sendResponseBodyPaced(
                stream_id,
                part,
                fin and sent == non_empty,
            );
        }
    }

    pub fn sendResponseBodyPartsPacedWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        parts: []const []const u8,
        fin: bool,
        progress: *BodyWriteProgress,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        progress.* = .{};
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseBodyPartsPacedWithDeadline(
            stream_id,
            parts,
            fin,
            progress,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Send borrowed response slices under one absolute deadline without
    /// joining them. Progress is the exact socket-visible byte prefix across
    /// all slices, allowing the caller to retry only the remaining suffix.
    pub fn sendResponseBodyPartsPacedWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        parts: []const []const u8,
        fin: bool,
        progress: *BodyWriteProgress,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        progress.* = .{};
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        const total_len = try bodyPartsLength(parts);
        try validateBodyWrite(&self.outbound_bodies, stream_id, total_len, fin);
        if (total_len == 0) {
            return self.sendResponseBodyPacedWithDeadline(
                stream_id,
                &.{},
                fin,
                progress,
                deadline,
            );
        }

        if (self.options.max_frames_per_packet < 2 or
            self.options.max_stream_frame_data == 0)
        {
            var non_empty: usize = 0;
            for (parts) |part| non_empty += @intFromBool(part.len != 0);
            var sent: usize = 0;
            for (parts) |part| {
                if (part.len == 0) continue;
                sent += 1;
                var part_progress: BodyWriteProgress = .{};
                self.sendResponseBodyPacedWithDeadline(
                    stream_id,
                    part,
                    fin and sent == non_empty,
                    &part_progress,
                    deadline,
                ) catch |err| {
                    progress.committed_bytes += part_progress.committed_bytes;
                    progress.fin_committed = part_progress.fin_committed;
                    return err;
                };
                progress.committed_bytes += part_progress.committed_bytes;
                progress.fin_committed = part_progress.fin_committed;
            }
            return;
        }

        var cursor = BodyPartCursor{ .parts = parts };
        var chunk_storage: [max_paced_body_part_descriptors][]const u8 = undefined;
        const chunk_limit = pacedBodyChunkLimit(self.options);
        while (!cursor.done()) {
            var attempt_limit = chunk_limit;
            while (true) {
                _ = try deadline_policy.usableAwake(
                    self.connectionIo(),
                    deadline,
                );
                var staged = cursor;
                const chunk = staged.next(
                    &chunk_storage,
                    attempt_limit,
                    self.options.max_stream_frame_data,
                );
                const last = staged.done();
                if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
                    return responseResetError(cancel.application_error_code);
                }
                trySendConnectionBodyParts(
                    &self.established.connection,
                    &self.outbound_bodies,
                    stream_id,
                    chunk,
                    fin and last,
                    self.options,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    error.PacingLimited => {
                        try self.established.connection
                            .waitForPacingAvailabilityWithDeadline(deadline);
                        continue;
                    },
                    error.DatagramTooLarge => {
                        if (attempt_limit == 1) return err;
                        attempt_limit = @max(@as(usize, 1), attempt_limit / 2);
                        continue;
                    },
                    else => return err,
                };
                progress.committed_bytes += bodyPartChunkLength(chunk);
                progress.fin_committed = fin and last;
                cursor = staged;
                break;
            }
        }
        if (fin) {
            finishServerRequest(
                &self.control,
                &self.request_lifecycle,
                stream_id,
            );
        }
    }

    /// Batched counterpart to `sendResponseBodyPaced` for concurrent response
    /// streams. Each contribution becomes one QUIC packet and the socket-visible
    /// prefix commits atomically into the corresponding body stream states.
    pub fn sendResponseBodyBatchPaced(
        self: *HandshakeServerSession,
        chunks: []const BodyChunk,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        try sendConnectionBodyBatchPaced(
            &self.established.connection,
            &self.outbound_bodies,
            chunks,
            self.options,
            self,
            HandshakeServerSession.receiveBatchProgressForSend,
            HandshakeServerSession.finishBatchResponseStream,
        );
    }

    pub fn sendResponseBodyBatchPacedWithTimeout(
        self: *HandshakeServerSession,
        chunks: []const BodyChunk,
        committed_chunks: *usize,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        committed_chunks.* = 0;
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseBodyBatchPacedWithDeadline(
            chunks,
            committed_chunks,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Send one DATA contribution per response stream under one caller-owned
    /// deadline. `committed_chunks` is the exact socket-visible input prefix
    /// and remains valid on timeout or a socket error.
    pub fn sendResponseBodyBatchPacedWithDeadline(
        self: *HandshakeServerSession,
        chunks: []const BodyChunk,
        committed_chunks: *usize,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        committed_chunks.* = 0;
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return sendConnectionBodyBatchPacedWithDeadline(
            &self.established.connection,
            &self.outbound_bodies,
            chunks,
            self.options,
            self,
            HandshakeServerSession.receiveBatchProgressForSendUntil,
            HandshakeServerSession.finishBatchResponseStream,
            committed_chunks,
            deadline,
        );
    }

    /// Send complete response bodies using RFC 9218 request priorities.
    ///
    /// This is the multi-stream blocking counterpart to
    /// `sendResponseBodyPaced`. The scheduler evaluates current QUIC credit
    /// before each packet pass, gives a received PRIORITY_UPDATE precedence
    /// over the request's Priority field, serializes non-incremental responses
    /// by stream ID, and round-robins incremental peers. Processing packets
    /// between blocked passes also makes live priority updates affect the next
    /// unsent DATA packet rather than only future API calls.
    pub fn sendResponseBodiesPaced(
        self: *HandshakeServerSession,
        responses: []const ResponseBody,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.sendResponseBodiesPacedUntil(
            responses,
            null,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponseBodiesPacedWithTimeout(
        self: *HandshakeServerSession,
        responses: []const ResponseBody,
        committed_bytes: []usize,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (committed_bytes.len < responses.len) return error.BufferTooShort;
        @memset(committed_bytes[0..responses.len], 0);
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseBodiesPacedWithDeadline(
            responses,
            committed_bytes,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Priority-schedule complete response bodies under one absolute deadline.
    /// Each `committed_bytes[index]` value is updated only after the
    /// corresponding DATA packet is accepted by the socket and remains valid
    /// on every error return.
    pub fn sendResponseBodiesPacedWithDeadline(
        self: *HandshakeServerSession,
        responses: []const ResponseBody,
        committed_bytes: []usize,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (committed_bytes.len < responses.len) return error.BufferTooShort;
        @memset(committed_bytes[0..responses.len], 0);
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendResponseBodiesPacedUntil(
            responses,
            committed_bytes,
            deadline,
        );
    }

    fn sendResponseBodiesPacedUntil(
        self: *HandshakeServerSession,
        responses: []const ResponseBody,
        committed_bytes: ?[]usize,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (responses.len == 0) return;
        const allocator =
            self.established.connection.endpoint.allocator;
        var workspace: response_scheduler.Workspace(
            quic.one_rtt.max_batch_packets,
        ) = .{};
        try workspace.init(allocator, responses.len);
        defer workspace.deinit(allocator);
        const candidates = workspace.candidates();

        for (responses, 0..) |response, index| {
            const body = self.outbound_bodies.find(response.stream_id) orelse
                return error.UnexpectedStream;
            var staged = body.*;
            try self.outbound_bodies.prepareChunkForEntry(
                &staged,
                response.data.len,
                true,
            );
            if (!workspace.registerResponse(index, response.stream_id)) {
                return error.UnexpectedStream;
            }
        }

        var remaining_responses = responses.len;
        for (responses) |response| {
            if (response.data.len == 0) remaining_responses -= 1;
        }
        // Empty fixed-length bodies are normally closed by startResponse.
        // Reject an accidental open zero-length body rather than spinning
        // without a DATA contribution that can carry FIN.
        if (remaining_responses != responses.len) {
            return error.InvalidFrame;
        }

        const chunk_limit = pacedBodyChunkLimit(self.options);
        const max_batch_packets = response_scheduler.batchPacketLimit(
            self.options.response_scheduler_max_batch_packets,
            quic.one_rtt.max_batch_packets,
        );
        var next_stream: usize = 0;
        var delay_budget = response_scheduler.DelayBudget{};
        while (remaining_responses != 0) {
            if (deadline) |absolute| {
                _ = try deadline_policy.usableAwake(
                    self.connectionIo(),
                    absolute,
                );
            }
            const selection = self.refreshResponseCandidates(
                responses,
                candidates,
                chunk_limit,
            ) orelse {
                try self.receiveRequestPacketUntil(deadline);
                continue;
            };

            workspace.stageSelected(
                responses,
                selection,
                next_stream,
                chunk_limit,
                max_batch_packets,
            );
            if (workspace.chunks().len == 0) {
                try self.receiveRequestPacketUntil(deadline);
                continue;
            }

            const progress = sendConnectionBodyBatchPacedProgress(
                &self.established.connection,
                &self.outbound_bodies,
                workspace.chunks(),
                self.options,
                self,
                HandshakeServerSession.finishBatchResponseStream,
            ) catch |err| switch (err) {
                error.FlowControlBlocked, error.CongestionLimited => {
                    try self.receiveRequestPacketUntil(deadline);
                    continue;
                },
                error.PacingLimited => {
                    if (deadline) |absolute| {
                        try self.established.connection
                            .waitForPacingAvailabilityWithDeadline(absolute);
                    } else {
                        try self.established.connection
                            .waitForPacingAvailability();
                    }
                    continue;
                },
                else => return err,
            };
            if (committed_bytes) |counts| {
                for (workspace.chunks()[0..progress.sent_count], 0..) |chunk, batch_index| {
                    const response_index = workspace.responseIndex(batch_index);
                    counts[response_index] += chunk.data.len;
                }
            }
            const commit = workspace.commitSentPrefix(progress.sent_count);
            remaining_responses -= commit.completed_responses;
            delay_budget.record(commit.body_bytes, progress.sent_count);
            if (progress.send_error) |err| return err;
            if (remaining_responses != 0 and
                self.options.response_scheduler_batch_delay_ns != 0 and
                delay_budget.due(
                    self.options.response_scheduler_batch_delay_bytes,
                    self.options.response_scheduler_batch_delay_packets,
                ))
            {
                const delay_ns = std.math.cast(
                    i64,
                    self.options.response_scheduler_batch_delay_ns,
                ) orelse std.math.maxInt(i64);
                try sleepResponseSchedulerDelayUntil(
                    self.connectionIo(),
                    delay_ns,
                    deadline,
                );
                delay_budget.reset();
            }
            if (selection.exclusive_index == null) {
                // Rotate only incremental passes. An exclusive stream retains
                // ownership until completion unless it becomes blocked or a
                // live PRIORITY_UPDATE changes the selected class.
                next_stream = (commit.last_response_index.? + 1) %
                    responses.len;
            }
        }
    }

    fn refreshResponseCandidates(
        self: *HandshakeServerSession,
        responses: []const ResponseBody,
        candidates: []response_scheduler.Candidate,
        chunk_limit: usize,
    ) ?response_scheduler.Selection {
        std.debug.assert(responses.len == candidates.len);
        var selection: response_scheduler.SelectionAccumulator = .{};
        const quic_connection = &self.established.connection;
        const connection_available = std.math.cast(
            usize,
            quic_connection.connectionSendAvailable(),
        ) orelse std.math.maxInt(usize);
        const congestion_available = quic_connection.congestionAvailable();
        const max_datagram_size = quic_connection.currentSendDatagramSize();
        for (responses, candidates, 0..) |response, *candidate, index| {
            const offset = candidate.offset;
            const remaining = response.data.len - offset;
            const stream_available = std.math.cast(
                usize,
                quic_connection.streamSendAvailable(
                    response.stream_id,
                ),
            ) orelse std.math.maxInt(usize);
            candidate.* = .{
                .stream_id = response.stream_id,
                .offset = offset,
                .remaining = remaining,
                .send_capacity = responseBodySendCapacity(
                    remaining,
                    connection_available,
                    stream_available,
                    congestion_available,
                    max_datagram_size,
                    chunk_limit,
                ),
                .priority = self.effectiveResponsePriority(
                    response.stream_id,
                ),
            };
            selection.consider(candidate.*, index);
        }
        return selection.result();
    }

    fn effectiveResponsePriority(
        self: HandshakeServerSession,
        stream_id: u62,
    ) http3.Priority {
        return self.request_lifecycle.priority(stream_id);
    }

    fn receiveBatchProgressForSend(
        self: *HandshakeServerSession,
    ) Error!void {
        try self.receiveRequestPacket();
    }

    fn receiveBatchProgressForSendUntil(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        try self.receiveRequestPacketUntil(deadline);
    }

    fn finishBatchResponseStream(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) void {
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    fn sendResponseBodyPacedChunk(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
    ) Error!void {
        return self.sendResponseBodyPacedChunkUntil(
            stream_id,
            data,
            fin,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    fn sendResponseBodyPacedChunkUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        data: []const u8,
        fin: bool,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        while (true) {
            if (deadline) |absolute| {
                if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
                    return responseResetError(cancel.application_error_code);
                }
                sendConnectionBodyChunkWithDeadline(
                    &self.established.connection,
                    &self.outbound_bodies,
                    stream_id,
                    data,
                    fin,
                    self.options,
                    absolute,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    else => |other| return other,
                };
                if (fin) finishServerRequest(
                    &self.control,
                    &self.request_lifecycle,
                    stream_id,
                );
                return;
            }
            self.sendResponseBody(stream_id, data, fin) catch |err| switch (err) {
                error.FlowControlBlocked, error.CongestionLimited => {
                    try self.receiveRequestPacketUntil(deadline);
                    continue;
                },
                else => |other| return other,
            };
            return;
        }
    }

    pub fn finishResponseTrailers(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
            return responseResetError(cancel.application_error_code);
        }
        try sendConnectionTrailers(
            &self.established.connection,
            &self.outbound_bodies,
            &self.stream_send_scratch,
            &self.critical_stream_send_scratch,
            stream_id,
            trailers,
            self.control.settings.peer,
            &self.qpack_encode,
            &self.qpack_encoder_send,
            &self.qpack_encoder_prefix_sent,
            self.options,
        );
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    /// Submit response trailers without waiting for pacing or reading UDP.
    /// Static QPACK encoding and stream state commit only after the one-packet
    /// send succeeds, so an endpoint loop may retry after dispatcher progress.
    pub fn tryFinishResponseTrailers(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
    ) Error!void {
        if (try self.finishPeerResponseCancellationOnce(stream_id)) |cancel| {
            return responseResetError(cancel.application_error_code);
        }
        try trySendConnectionTrailersLiteral(
            &self.established.connection,
            &self.outbound_bodies,
            &self.stream_send_scratch,
            stream_id,
            trailers,
            self.control.settings.peer,
            self.options,
        );
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    /// Wait until the peer cancels the response direction of `stream_id`.
    ///
    /// The request itself can already be complete: closing an unread response
    /// body sends STOP_SENDING, not RESET_STREAM, so it must be observed from
    /// the local QUIC send state. Packets for unrelated request streams remain
    /// routed while this blocking convenience method waits.
    pub fn receivePeerResponseCancellation(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!PeerResponseCancellation {
        return self.receivePeerResponseCancellationUntil(
            stream_id,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn receivePeerResponseCancellationWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!PeerResponseCancellation {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.receivePeerResponseCancellationWithDeadline(
            stream_id,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Wait for peer STOP_SENDING under one absolute deadline. Cancellation
    /// delivery registers stream retirement without waiting for a paced
    /// MAX_STREAMS update; the connection timer completes that retry.
    pub fn receivePeerResponseCancellationWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!PeerResponseCancellation {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.receivePeerResponseCancellationUntil(
            stream_id,
            deadline,
        );
    }

    fn receivePeerResponseCancellationUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!PeerResponseCancellation {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (!self.request_lifecycle.contains(stream_id)) {
            return error.UnexpectedStream;
        }
        while (true) {
            const cancellation = if (deadline != null)
                try self.finishPeerResponseCancellationOnce(stream_id)
            else
                try self.finishPeerResponseCancellation(stream_id);
            if (cancellation) |cancel| {
                return cancel;
            }
            try self.receiveRequestPacketUntil(deadline);
        }
    }

    fn finishPeerResponseCancellation(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!?PeerResponseCancellation {
        const stopped = self.established.connection.streamStopped(stream_id) orelse
            return null;
        // Do the only fallible cleanup first. If sending MAX_STREAMS is
        // temporarily blocked, the caller can retry without losing the
        // cancellation or partially retiring HTTP/3 bookkeeping.
        _ = try self.established.connection.releaseCompletedPeerStream(
            stream_id,
        );
        self.qpack_encode.abandonStream(stream_id);
        _ = self.outbound_bodies.finish(stream_id);
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
        return .{
            .stream_id = stream_id,
            .application_error_code = stopped.application_error_code,
        };
    }

    /// Cancellation cleanup for event-loop send attempts. Stream retirement
    /// is registered for timer-driven retry so this path cannot wait for
    /// pacing while reporting that the response direction was cancelled.
    fn finishPeerResponseCancellationOnce(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!?PeerResponseCancellation {
        const stopped = self.established.connection.streamStopped(stream_id) orelse
            return null;
        _ = try self.established.connection.requestCompletedPeerStreamRelease(
            stream_id,
        );
        self.qpack_encode.abandonStream(stream_id);
        _ = self.outbound_bodies.finish(stream_id);
        finishServerRequest(
            &self.control,
            &self.request_lifecycle,
            stream_id,
        );
        return .{
            .stream_id = stream_id,
            .application_error_code = stopped.application_error_code,
        };
    }

    /// Blocking counterpart to `finishResponseTrailers` that keeps receiving
    /// request-side packets until the response trailers can be written.
    pub fn finishResponseTrailersPaced(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.finishResponseTrailersPacedUntil(
            stream_id,
            trailers,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn finishResponseTrailersPacedWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.finishResponseTrailersPacedWithDeadline(
            stream_id,
            trailers,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    /// Finish a streaming response with trailers under one absolute deadline.
    /// A timeout before any packet is visible is retryable; a timeout after a
    /// multi-packet QPACK/trailer prefix uses the packetizer's fail-closed rule.
    pub fn finishResponseTrailersPacedWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.finishResponseTrailersPacedUntil(
            stream_id,
            trailers,
            deadline,
        );
    }

    fn finishResponseTrailersPacedUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        trailers: []const http3.Qpack.HeaderField,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        while (true) {
            if (deadline) |absolute| {
                if (try self.finishPeerResponseCancellation(stream_id)) |cancel| {
                    return responseResetError(cancel.application_error_code);
                }
                sendConnectionTrailersWithDeadline(
                    &self.established.connection,
                    &self.outbound_bodies,
                    &self.stream_send_scratch,
                    &self.critical_stream_send_scratch,
                    stream_id,
                    trailers,
                    self.control.settings.peer,
                    &self.qpack_encode,
                    &self.qpack_encoder_send,
                    &self.qpack_encoder_prefix_sent,
                    self.options,
                    absolute,
                ) catch |err| switch (err) {
                    error.FlowControlBlocked, error.CongestionLimited => {
                        try self.receiveRequestPacketUntil(deadline);
                        continue;
                    },
                    else => |other| return other,
                };
                finishServerRequest(
                    &self.control,
                    &self.request_lifecycle,
                    stream_id,
                );
                return;
            }
            self.finishResponseTrailers(stream_id, trailers) catch |err| switch (err) {
                error.FlowControlBlocked, error.CongestionLimited => {
                    try self.receiveRequestPacketUntil(deadline);
                    continue;
                },
                else => |other| return other,
            };
            return;
        }
    }

    pub fn sendResponseWithInformational(
        self: *HandshakeServerSession,
        stream_id: u62,
        informational: []const http3.InformationalResponse,
        response: http3.Response,
    ) Error!void {
        return self.sendResponseWithInformationalUntil(
            stream_id,
            informational,
            response,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendResponseWithInformationalAndTimeout(
        self: *HandshakeServerSession,
        stream_id: u62,
        informational: []const http3.InformationalResponse,
        response: http3.Response,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendResponseWithInformationalAndDeadline(
            stream_id,
            informational,
            response,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    pub fn sendResponseWithInformationalAndDeadline(
        self: *HandshakeServerSession,
        stream_id: u62,
        informational: []const http3.InformationalResponse,
        response: http3.Response,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendResponseWithInformationalUntil(
            stream_id,
            informational,
            response,
            deadline,
        );
    }

    fn sendResponseWithInformationalUntil(
        self: *HandshakeServerSession,
        stream_id: u62,
        informational: []const http3.InformationalResponse,
        response: http3.Response,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (deadline) |absolute| {
            try sendConnectionSettingsWithDeadline(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
                absolute,
            );
        } else {
            try sendConnectionSettings(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
            );
        }
        var response_headers_stack: [server_response.header_stack_capacity]http3.Qpack.HeaderField =
            undefined;
        var prepared = try server_response.prepare(
            self.established.connection.endpoint.allocator,
            response,
            server_response.automaticDate(
                self.options.auto_date_header,
                self.established.connection.endpoint.io,
                response,
            ),
            &response_headers_stack,
        );
        defer prepared.deinit(
            self.established.connection.endpoint.allocator,
        );
        if (deadline) |absolute| {
            try sendConnectionResponseSequenceWithDeadline(
                &self.established.connection,
                &self.stream_send_scratch,
                &self.critical_stream_send_scratch,
                stream_id,
                informational,
                prepared.value,
                self.options,
                self.control.settings.peer,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                absolute,
            );
        } else {
            try sendConnectionResponseSequence(
                &self.established.connection,
                &self.stream_send_scratch,
                &self.critical_stream_send_scratch,
                stream_id,
                informational,
                prepared.value,
                self.options,
                self.control.settings.peer,
                &self.qpack_encode,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
            );
        }
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
    }

    pub fn sendGoAway(self: *HandshakeServerSession, stream_id: u64) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        try validateServerGoAwayStreamId(stream_id);
        try sendConnectionSettings(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.control,
            &self.control_send,
            &self.qpack_encoder_send,
            &self.qpack_encoder_prefix_sent,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
            server_control_stream_id,
        );
        try sendConnectionControlFrame(&self.established.connection, &self.control, &self.control_send, self.options, .goaway, stream_id);
    }

    pub fn sendGoAwayWithTimeout(
        self: *HandshakeServerSession,
        stream_id: u64,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendGoAwayWithDeadline(stream_id, .fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn sendGoAwayWithDeadline(
        self: *HandshakeServerSession,
        stream_id: u64,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        try validateServerGoAwayStreamId(stream_id);
        try sendConnectionSettingsWithDeadline(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.control,
            &self.control_send,
            &self.qpack_encoder_send,
            &self.qpack_encoder_prefix_sent,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
            server_control_stream_id,
            deadline,
        );
        try sendConnectionControlFrameWithDeadline(
            &self.established.connection,
            &self.control,
            &self.control_send,
            self.options,
            .goaway,
            stream_id,
            deadline,
        );
    }

    /// Submit GOAWAY once without waiting for pacing or reading UDP. Promoted
    /// endpoint sessions retry after dispatcher progress.
    pub fn trySendGoAway(
        self: *HandshakeServerSession,
        stream_id: u64,
    ) Error!void {
        try validateServerGoAwayStreamId(stream_id);
        try self.requireEndpointCriticalStreamsReady();
        try trySendConnectionControlFrame(
            &self.established.connection,
            &self.control,
            &self.control_send,
            self.options,
            .goaway,
            stream_id,
        );
    }

    /// Advertise RFC 9412 origins on the server control stream. Clients must
    /// still validate certificate authority before coalescing requests.
    pub fn sendOrigins(
        self: *HandshakeServerSession,
        origins: []const []const u8,
    ) Error!void {
        return self.sendOriginsUntil(origins, null) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn sendOriginsWithTimeout(
        self: *HandshakeServerSession,
        origins: []const []const u8,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.sendOriginsWithDeadline(
            origins,
            .fromNow(self.connectionIo(), .{
                .raw = timeout,
                .clock = .awake,
            }),
        );
    }

    pub fn sendOriginsWithDeadline(
        self: *HandshakeServerSession,
        origins: []const []const u8,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.sendOriginsUntil(origins, deadline);
    }

    fn sendOriginsUntil(
        self: *HandshakeServerSession,
        origins: []const []const u8,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (deadline) |absolute| {
            try sendConnectionSettingsWithDeadline(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
                absolute,
            );
        } else {
            try sendConnectionSettings(
                &self.established.connection,
                &self.critical_stream_send_scratch,
                &self.control,
                &self.control_send,
                &self.qpack_encoder_send,
                &self.qpack_encoder_prefix_sent,
                &self.qpack_decoder_send,
                &self.qpack_decoder_prefix_sent,
                self.options,
                server_control_stream_id,
            );
        }
        const previous_sent = self.control.local_origin_set_sent;
        errdefer self.control.local_origin_set_sent = previous_sent;
        self.critical_stream_send_scratch.reset();
        try self.control.writeOrigins(
            &self.critical_stream_send_scratch.payload,
            self.established.connection.endpoint.allocator,
            origins,
        );
        const previous_send = self.control_send;
        errdefer self.control_send = previous_send;
        try self.control_send.appendFrames(
            &self.critical_stream_send_scratch.frames,
            self.established.connection.endpoint.allocator,
            self.critical_stream_send_scratch.payload.items,
            self.options.max_stream_frame_data,
            false,
        );
        if (deadline) |absolute| {
            try sendConnectionFramesWithDeadline(
                &self.established.connection,
                self.critical_stream_send_scratch.frames.items,
                self.options.max_frames_per_packet,
                absolute,
            );
        } else {
            try sendConnectionFrames(
                &self.established.connection,
                self.critical_stream_send_scratch.frames.items,
                self.options.max_frames_per_packet,
            );
        }
    }

    /// Submit one complete RFC 9412 ORIGIN frame without waiting for pacing
    /// or reading UDP. The advertisement marker and control-stream offset are
    /// committed only after the packet reaches the socket.
    pub fn trySendOrigins(
        self: *HandshakeServerSession,
        origins: []const []const u8,
    ) Error!void {
        try self.requireEndpointCriticalStreamsReady();
        const previous_sent = self.control.local_origin_set_sent;
        errdefer self.control.local_origin_set_sent = previous_sent;
        self.critical_stream_send_scratch.reset();
        try self.control.writeOrigins(
            &self.critical_stream_send_scratch.payload,
            self.established.connection.endpoint.allocator,
            origins,
        );
        const previous_send = self.control_send;
        errdefer self.control_send = previous_send;
        try self.control_send.appendFrames(
            &self.critical_stream_send_scratch.frames,
            self.established.connection.endpoint.allocator,
            self.critical_stream_send_scratch.payload.items,
            self.options.max_stream_frame_data,
            false,
        );
        if (self.critical_stream_send_scratch.frames.items.len >
            @max(@as(usize, 1), self.options.max_frames_per_packet) or
            try self.established.connection.packetLenForFramesAtOffset(
                0,
                self.critical_stream_send_scratch.frames.items,
            ) > self.established.connection.currentSendDatagramSize())
        {
            return error.DatagramTooLarge;
        }
        try self.established.connection.trySend(
            self.critical_stream_send_scratch.frames.items,
        );
    }

    pub fn initiateShutdown(self: *HandshakeServerSession) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (self.request_lifecycle.state() != .active) return;
        try self.sendGoAway(@as(u64, quic.varint.max_value) & ~@as(u64, 0x3));
        self.request_lifecycle.markInitialGoAwaySent();
    }

    pub fn initiateShutdownWithTimeout(
        self: *HandshakeServerSession,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.initiateShutdownWithDeadline(.fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn initiateShutdownWithDeadline(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        if (self.request_lifecycle.state() != .active) return;
        try self.sendGoAwayWithDeadline(
            @as(u64, quic.varint.max_value) & ~@as(u64, 0x3),
            deadline,
        );
        self.request_lifecycle.markInitialGoAwaySent();
    }

    pub fn tryInitiateShutdown(
        self: *HandshakeServerSession,
    ) Error!void {
        if (self.request_lifecycle.state() != .active) return;
        try self.trySendGoAway(
            @as(u64, quic.varint.max_value) & ~@as(u64, 0x3),
        );
        self.request_lifecycle.markInitialGoAwaySent();
    }

    pub fn completeShutdown(self: *HandshakeServerSession) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (self.request_lifecycle.state() != .initial_goaway) return;
        if (!self.request_streams.isEmpty() or
            self.streaming_requests.retainedCount() != 0)
        {
            return error.RequestIncomplete;
        }
        try self.sendGoAway(try self.request_lifecycle.finalGoAwayId());
        self.request_lifecycle.markFinalGoAwaySent();
    }

    pub fn completeShutdownWithTimeout(
        self: *HandshakeServerSession,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.completeShutdownWithDeadline(.fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn completeShutdownWithDeadline(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        if (self.request_lifecycle.state() != .initial_goaway) return;
        if (!self.request_streams.isEmpty() or
            self.streaming_requests.retainedCount() != 0)
        {
            return error.RequestIncomplete;
        }
        try self.sendGoAwayWithDeadline(
            try self.request_lifecycle.finalGoAwayId(),
            deadline,
        );
        self.request_lifecycle.markFinalGoAwaySent();
    }

    pub fn tryCompleteShutdown(
        self: *HandshakeServerSession,
    ) Error!void {
        if (self.request_lifecycle.state() != .initial_goaway) return;
        if (!self.request_streams.isEmpty() or
            self.streaming_requests.retainedCount() != 0)
        {
            return error.RequestIncomplete;
        }
        try self.trySendGoAway(try self.request_lifecycle.finalGoAwayId());
        self.request_lifecycle.markFinalGoAwaySent();
    }

    pub fn drainComplete(self: HandshakeServerSession) bool {
        return self.request_lifecycle.drainComplete(
            self.request_streams.lowestStream(),
            self.streaming_requests.lowestEntryStream(),
            self.streaming_requests.lowestResetStream(),
            self.control.local_goaway_id,
        );
    }

    pub fn cancelRequest(
        self: *HandshakeServerSession,
        stream_id: u62,
        application_error_code: u64,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        return self.cancelRequestInternal(
            stream_id,
            application_error_code,
            false,
        );
    }

    /// Cancel one request without waiting for transport pacing. Endpoint-wide
    /// protocol adapters retry this after dispatcher progress so they retain a
    /// single UDP receive owner and never sleep inside packet routing.
    pub fn tryCancelRequest(
        self: *HandshakeServerSession,
        stream_id: u62,
        application_error_code: u64,
    ) Error!void {
        return self.cancelRequestInternalOnce(
            stream_id,
            application_error_code,
            false,
        );
    }

    fn cancelRequestInternal(
        self: *HandshakeServerSession,
        stream_id: u62,
        application_error_code: u64,
        decoded_dynamic_section: bool,
    ) Error!void {
        var cancel_qpack = decoded_dynamic_section;
        if (!cancel_qpack) {
            cancel_qpack = try self.request_streams.requiresQpackCancellation(
                stream_id,
                self.qpack_decode.table,
            );
        }
        if (!cancel_qpack) {
            cancel_qpack =
                try self.streaming_requests.hasUnacknowledgedDynamicSection(
                    stream_id,
                    self.qpack_decode.table,
                );
        }
        defer {
            self.request_streams.remove(stream_id);
            self.streaming_requests.remove(stream_id);
            self.qpack_encode.abandonStream(stream_id);
            finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
            _ = self.outbound_bodies.finish(stream_id);
        }
        errdefer self.established.connection.failClosedApplication(
            http3.ApplicationErrorCode.internal_error,
            "request-cancellation-failed",
        );
        try cancelConnectionRequest(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.qpack_decode,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
            stream_id,
            application_error_code,
            cancel_qpack,
        );
    }

    fn cancelRequestInternalOnce(
        self: *HandshakeServerSession,
        stream_id: u62,
        application_error_code: u64,
        decoded_dynamic_section: bool,
    ) Error!void {
        var cancel_qpack = decoded_dynamic_section;
        if (!cancel_qpack) {
            cancel_qpack = try self.request_streams.requiresQpackCancellation(
                stream_id,
                self.qpack_decode.table,
            );
        }
        if (!cancel_qpack) {
            cancel_qpack =
                try self.streaming_requests.hasUnacknowledgedDynamicSection(
                    stream_id,
                    self.qpack_decode.table,
                );
        }
        if (cancel_qpack) {
            try self.qpack_decode.prepareStreamCancellation();
        }
        try self.established.connection.tryCancelStream(
            stream_id,
            application_error_code,
        );
        if (cancel_qpack) {
            self.qpack_decode.recordStreamCancellationAssumeCapacity(
                stream_id,
            );
        }
        self.request_streams.remove(stream_id);
        self.streaming_requests.remove(stream_id);
        self.qpack_encode.abandonStream(stream_id);
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
        _ = self.outbound_bodies.finish(stream_id);
    }

    pub fn rejectRequest(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        try self.cancelRequest(
            stream_id,
            http3.ApplicationErrorCode.request_rejected,
        );
    }

    /// Stop and retire the request direction after a complete final response
    /// has already closed the response direction. Late STREAM/RESET frames are
    /// retained by QUIC for final-size validation but no longer re-enter the
    /// HTTP/3 request queues.
    pub fn finishRejectedRequest(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        const exists = self.request_lifecycle.contains(stream_id) or
            self.request_streams.contains(stream_id) or
            self.streaming_requests.contains(stream_id) or
            self.outbound_bodies.find(stream_id) != null;
        if (!exists) return error.UnexpectedStream;
        var cancel_qpack = try self.request_streams.requiresQpackCancellation(
            stream_id,
            self.qpack_decode.table,
        );
        cancel_qpack = cancel_qpack or
            try self.streaming_requests.hasUnacknowledgedDynamicSection(
                stream_id,
                self.qpack_decode.table,
            );
        if (self.streaming_requests.find(stream_id)) |entry| {
            try releaseStreamingReaderCapacity(
                &self.established.connection,
                &entry.reader,
            );
        }
        try self.established.connection.sendStopSending(
            stream_id,
            http3.ApplicationErrorCode.request_cancelled,
        );
        if (cancel_qpack) {
            try self.qpack_decode.recordStreamCancellation(stream_id);
        }
        self.request_streams.remove(stream_id);
        self.streaming_requests.remove(stream_id);
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
        _ = self.outbound_bodies.finish(stream_id);
        try self.sendQpackFeedback();
    }

    /// Release local request bookkeeping after a final non-success response
    /// has closed the response direction. No RESET_STREAM or STOP_SENDING is
    /// emitted; callers use `cancelRequest` when peer-visible cancellation is
    /// required.
    pub fn finishRequest(
        self: *HandshakeServerSession,
        stream_id: u62,
    ) Error!void {
        const exists = self.request_lifecycle.contains(stream_id) or
            self.request_streams.contains(stream_id) or
            self.streaming_requests.contains(stream_id) or
            self.outbound_bodies.find(stream_id) != null;
        if (!exists) return error.UnexpectedStream;
        self.request_streams.remove(stream_id);
        self.streaming_requests.remove(stream_id);
        self.qpack_encode.abandonStream(stream_id);
        finishServerRequest(&self.control, &self.request_lifecycle, stream_id);
        _ = self.outbound_bodies.finish(stream_id);
    }

    fn receiveRequestPacket(self: *HandshakeServerSession) Error!void {
        return self.receiveRequestPacketUntil(null) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    fn receiveRequestPacketUntil(
        self: *HandshakeServerSession,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (deadline) |absolute| {
            try self.receive_packets.visitWithDeadline(
                &self.established.connection,
                absolute,
                self,
                visitStreamingServerRequestPacket,
            );
        } else {
            try self.receive_packets.visit(
                &self.established.connection,
                self,
                visitStreamingServerRequestPacket,
            );
        }
        // Encoder-stream inserts and reset cancellations both queue decoder
        // instructions. Flush them at the packet boundary so a peer does not
        // remain artificially blocked until another HEADERS event appears.
        if (deadline) |absolute| {
            try self.flushRequestPacketFeedbackWithDeadline(absolute);
        } else {
            try self.flushRequestPacketFeedback();
        }
    }

    fn receiveAttachedConnectDatagramProgress(
        self: *HandshakeServerSession,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        return self.receiveRequestPacketUntil(deadline);
    }

    fn flushRequestPacketFeedback(self: *HandshakeServerSession) Error!void {
        if (self.qpack_decode.pendingDecoderInstructions().len != 0) {
            try self.sendQpackFeedback();
        }
    }

    fn flushRequestPacketFeedbackWithDeadline(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.qpack_decode.pendingDecoderInstructions().len == 0) return;
        try sendConnectionQpackFeedbackWithDeadline(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.qpack_decode,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
            deadline,
        );
    }

    /// Process one transport packet for control-stream progress without
    /// requiring a complete application request to become ready.
    pub fn pollControl(self: *HandshakeServerSession) Error!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        try self.receiveRequestPacket();
    }

    pub fn pollControlWithTimeout(
        self: *HandshakeServerSession,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.receiveRequestPacketUntil(.fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn pollControlWithDeadline(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        return self.receiveRequestPacketUntil(deadline);
    }

    /// Drive ACK, loss, PTO, flow-control, and HTTP/3 control processing until
    /// every packet required to deliver the completed response has been
    /// acknowledged. Pure MAX_DATA/MAX_STREAMS updates remain under QUIC's
    /// normal recovery timer but do not prolong a short-lived server whose
    /// final application data is already safe.
    /// Response writers return after socket submission so persistent servers
    /// do not pay an ACK round trip per response; short-lived owners should
    /// drain before destroying the session so a dropped final DATA/FIN remains
    /// recoverable. Incoming request bytes stay routed to their normal queues.
    pub fn waitForRecoveryIdleWithTimeout(
        self: *HandshakeServerSession,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.waitForRecoveryIdleWithDeadline(.fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn waitForRecoveryIdleWithDeadline(
        self: *HandshakeServerSession,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!void {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        _ = try deadline_policy.usableAwake(self.connectionIo(), deadline);
        while (self.established.connection.pendingDeliveryRecovery()) {
            try self.receiveRequestPacketUntil(deadline);
        }
    }

    fn applyStreamingRequestEvent(
        self: *HandshakeServerSession,
        entry: *StreamingRequestSet.Entry,
        event: StreamingEvent,
        single_attempt: bool,
    ) Error!StreamingRequestEvent {
        const stream_id = entry.reader.streamId();
        const from = entry.from orelse unreachable;
        // Capture provenance before a finished event can release and compact
        // a stream whose response send half is already acknowledged.
        const was_early_data = self.established.connection
            .recvStreamReceivedEarlyData(stream_id);
        if (try streamingRequestSectionAcknowledgments(event)) |count| {
            self.qpack_decode.acknowledgeSectionsAssumeCapacity(
                stream_id,
                count,
            );
            if (single_attempt)
                self.flushRequestPacketFeedbackOnce() catch {}
            else
                self.sendQpackFeedback() catch {};
        }
        if (event == .head) {
            serverRequestReceivedAssumeCapacity(
                &self.control,
                &self.request_lifecycle,
                stream_id,
                switch (event) {
                    .head => |head| switch (head) {
                        .request => |request| requestPriority(
                            request.headers,
                        ),
                        .response => .{},
                    },
                    else => .{},
                },
            );
        } else if (event == .finished) {
            _ = try self.established.connection
                .requestCompletedPeerStreamRelease(stream_id);
            self.streaming_requests.remove(stream_id);
        }
        return .{ .message = .{
            .from = from,
            .stream_id = stream_id,
            .was_early_data = was_early_data,
            .value = event,
        } };
    }

    fn releaseStreamingRequestCapacity(
        self: *HandshakeServerSession,
    ) Error!void {
        var index: usize = 0;
        while (self.streaming_requests.entryAt(index)) |entry| : (index += 1) {
            try releaseStreamingReaderCapacity(
                &self.established.connection,
                &entry.reader,
            );
        }
    }

    fn releaseStreamingRequestCapacityOnce(
        self: *HandshakeServerSession,
    ) Error!bool {
        var index: usize = 0;
        while (self.streaming_requests.entryAt(index)) |entry| : (index += 1) {
            releaseStreamingReaderCapacityOnce(
                &self.established.connection,
                &entry.reader,
            ) catch |err| switch (err) {
                error.PacingLimited,
                error.CongestionLimited,
                error.FlowControlBlocked,
                => return false,
                else => return err,
            };
        }
        return true;
    }

    fn connectionIo(self: *const HandshakeServerSession) std.Io {
        return self.established.connection.endpoint.io;
    }

    fn sendQpackFeedback(self: *HandshakeServerSession) Error!void {
        try sendConnectionQpackFeedback(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.qpack_decode,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
        );
    }

    fn flushRequestPacketFeedbackOnce(
        self: *HandshakeServerSession,
    ) Error!void {
        if (self.qpack_decode.pendingDecoderInstructions().len == 0) return;
        try trySendConnectionQpackFeedback(
            &self.established.connection,
            &self.critical_stream_send_scratch,
            &self.qpack_decode,
            &self.qpack_decoder_send,
            &self.qpack_decoder_prefix_sent,
            self.options,
        );
    }
};

fn sleepResponseSchedulerDelayUntil(
    io: std.Io,
    delay_ns: i64,
    deadline: ?std.Io.Clock.Timestamp,
) ReceiveTimeoutError!void {
    const delay = std.Io.Duration.fromNanoseconds(delay_ns);
    if (deadline) |absolute| {
        const remaining = (try deadline_policy.usableAwake(io, absolute))
            .durationFromNow(io).raw;
        if (delay.nanoseconds >= remaining.nanoseconds) {
            try std.Io.sleep(io, remaining, .awake);
            return error.Timeout;
        }
    }
    try std.Io.sleep(io, delay, .awake);
}

test "HTTP/3 response scheduler delay respects caller deadline" {
    const FixedIo = struct {
        now_ns: i96 = 1_000_000,
        sleep_calls: usize = 0,
        slept_ns: i96 = 0,

        fn now(
            userdata: ?*anyopaque,
            _: std.Io.Clock,
        ) std.Io.Timestamp {
            const self: *@This() = @ptrCast(@alignCast(userdata));
            return .fromNanoseconds(self.now_ns);
        }

        fn sleep(
            userdata: ?*anyopaque,
            timeout: std.Io.Timeout,
        ) std.Io.Cancelable!void {
            const self: *@This() = @ptrCast(@alignCast(userdata));
            self.sleep_calls += 1;
            const target = switch (timeout) {
                .none => return error.Canceled,
                .duration => |duration| self.now_ns + duration.raw.nanoseconds,
                .deadline => |deadline| deadline.raw.nanoseconds,
            };
            self.slept_ns += target - self.now_ns;
            self.now_ns = target;
        }
    };
    var fixed: FixedIo = .{};
    var vtable = std.Io.Threaded.init(std.testing.allocator, .{});
    defer vtable.deinit();
    var io_vtable = vtable.io().vtable.*;
    io_vtable.now = FixedIo.now;
    io_vtable.sleep = FixedIo.sleep;
    const io = std.Io{ .userdata = &fixed, .vtable = &io_vtable };
    const deadline = std.Io.Clock.Timestamp.fromNow(io, .{
        .raw = .fromMilliseconds(10),
        .clock = .awake,
    });
    try std.testing.expectError(
        error.Timeout,
        sleepResponseSchedulerDelayUntil(io, std.time.ns_per_s, deadline),
    );
    try std.testing.expectEqual(@as(usize, 1), fixed.sleep_calls);
    try std.testing.expectEqual(@as(i96, 10 * std.time.ns_per_ms), fixed.slept_ns);
}

pub const HandshakeClient = struct {
    endpoint: *quic.runtime.Endpoint,
    owns_endpoint: bool,
    /// Set while an endpoint dispatcher is the sole UDP receive owner.
    /// Socket-reading convenience methods fail closed in this mode; callers
    /// inject routed packets and use the `*Once` polling surface instead.
    dispatcher_bound: bool = false,
    /// Aggregate informational callbacks borrow decoded field storage and
    /// must not recursively advance this connection's receive state.
    callback_reader_active: bool = false,
    /// A best-effort dispatcher-side cleanup can retire HTTP/3 bookkeeping
    /// without successfully emitting every QUIC terminal frame. Such a
    /// connection must be discarded rather than returned to an idle pool.
    reuse_safe: bool = true,
    peer: net.IpAddress,
    allocator: std.mem.Allocator,
    established: quic.handshake.EstablishedConnection,
    options: HandshakeSessionOptions,
    control: http3.ControlState = .{},
    control_send: quic.stream_state.SendState = quic.stream_state.SendState.init(client_control_stream_id),
    qpack_decode: QpackDecodeState,
    qpack_encode: QpackEncodeState,
    qpack_encoder_send: quic.stream_state.SendState = quic.stream_state.SendState.init(client_qpack_encoder_stream_id),
    qpack_encoder_prefix_sent: bool = false,
    qpack_decoder_send: quic.stream_state.SendState = quic.stream_state.SendState.init(client_qpack_decoder_stream_id),
    qpack_decoder_prefix_sent: bool = false,
    response_streams: ResponseStreamSet,
    streaming_responses: StreamingResponseSet,
    push_streams: PushStreamSet,
    push_aggregate: ClientPushAggregateState = .{},
    receive_packets: ConnectionPacketCursor = .{},
    request_lifecycle: ClientRequestLifecycle,
    connect_datagrams: connect_datagram.Registry,
    outbound_bodies: OutboundBodySet,
    stream_send_scratch: StreamMessageSendScratch = .{},
    critical_stream_send_scratch: CriticalStreamSendScratch = .{},
    ticket_receiver: ticket_receiver.Receiver,
    next_stream_id: u62 = 0,

    /// Reserve one client-initiated bidirectional stream ID.
    ///
    /// Request streams and WebTransport bidirectional streams share this QUIC
    /// ID space. Protocol adapters must reserve through this method rather than
    /// maintaining an independent counter.
    pub fn reserveClientBidirectionalStreamId(
        self: *HandshakeClient,
    ) Error!u62 {
        const stream_id = self.next_stream_id;
        self.next_stream_id = std.math.add(
            u62,
            stream_id,
            4,
        ) catch return error.StreamCreationError;
        self.request_lifecycle.markAllocated(stream_id);
        return stream_id;
    }

    /// Reserve a client-initiated bidirectional ID in both HTTP/3's request
    /// namespace and QUIC. This cohesive operation prevents WebTransport from
    /// advancing either cursor while leaving the other behind.
    pub fn openClientBidirectionalStream(
        self: *HandshakeClient,
    ) Error!u62 {
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        const expected = self.next_stream_id;
        _ = std.math.add(u62, expected, 4) catch
            return error.StreamCreationError;
        if (self.established.connection
            .nextLocalBidirectionalStreamId() != expected)
        {
            return error.StreamCreationError;
        }
        const transport_id = try self.established.connection.openStream();
        const stream_id = try self.reserveClientBidirectionalStreamId();
        std.debug.assert(stream_id == expected and stream_id == transport_id);
        return stream_id;
    }

    /// Reserve one bidirectional stream without waiting for STREAMS_BLOCKED
    /// pacing. This is the dispatcher-safe counterpart to
    /// `openClientBidirectionalStream`.
    pub fn tryOpenClientBidirectionalStream(
        self: *HandshakeClient,
    ) Error!u62 {
        const expected = self.next_stream_id;
        const next_stream_id = std.math.add(u62, expected, 4) catch
            return error.StreamCreationError;
        if (self.established.connection.nextLocalBidirectionalStreamId() !=
            expected)
        {
            return error.StreamCreationError;
        }
        const transport_id = try self.established.connection.tryOpenStream();
        self.next_stream_id = next_stream_id;
        self.request_lifecycle.markAllocated(expected);
        std.debug.assert(expected == transport_id);
        return expected;
    }

    pub fn tryOpenClientBidirectionalStreamWithResetPrefix(self: *HandshakeClient, prefix: []const u8) Error!u62 {
        const expected = self.next_stream_id;
        const advanced = std.math.add(u62, expected, 4) catch return error.StreamCreationError;
        if (self.established.connection.nextLocalBidirectionalStreamId() != expected) return error.StreamCreationError;
        const actual = try self.established.connection.tryOpenStreamWithResetPrefix(.bidirectional, prefix);
        self.next_stream_id = advanced;
        self.request_lifecycle.markAllocated(expected);
        std.debug.assert(actual == expected);
        return expected;
    }

    pub fn openClientBidirectionalStreamWithTimeout(
        self: *HandshakeClient,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!u62 {
        if (self.callback_reader_active) return error.ConcurrentRead;
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.openClientBidirectionalStreamWithDeadline(.fromNow(
            self.connectionIo(),
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    pub fn openClientBidirectionalStreamWithDeadline(
        self: *HandshakeClient,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!u62 {
        if (self.callback_reader_active) return error.ConcurrentRead;
        if (self.dispatcher_bound) return error.InvalidDispatcherState;
        const expected = self.next_stream_id;
        _ = std.math.add(u62, expected, 4) catch
            return error.StreamCreationError;
        if (self.established.connection
            .nextLocalBidirectionalStreamId() != expected)
        {
            return error.StreamCreationError;
        }
        const transport_id = try self.established.connection
            .openStreamWithDeadline(deadline);
        const stream_id = try self.reserveClientBidirectionalStreamId();
        std.debug.assert(stream_id == expected and stream_id == transport_id);
        return stream_id;
    }

    fn requestStreamSendRetryable(
        self: *const HandshakeClient,
        stream_id: u62,
        next_stream_id: u62,
    ) bool {
        if (self.established.connection.closed() or
            self.established.connection.closing() or
            self.established.connection.draining() or
            self.established.connection.nextLocalBidirectionalStreamId() !=
                next_stream_id)
        {
            return false;
        }
        const stats = self.established.connection.sendStreamStats(stream_id) orelse
            return true;
        return stats.highest_sent_offset == 0 and
            stats.final_size == null and
            stats.stopped == null and
            stats.reset == null;
    }

    fn retireReservedRequestStreamId(
        self: *HandshakeClient,
        stream_id: u62,
    ) void {
        if (self.next_stream_id != stream_id) return;
        const next_stream_id = std.math.add(u62, stream_id, 4) catch return;
        if (self.established.connection.nextLocalBidirectionalStreamId() ==
            next_stream_id)
        {
            self.next_stream_id = next_stream_id;
        }
    }

    pub fn connect(allocator: std.mem.Allocator, io: std.Io, local_address: net.IpAddress, server: net.IpAddress, limits: Limits, options: HandshakeClientOptions) Error!HandshakeClient {
        return connectBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            try connectDeadline(io, options.connect_timeout),
            null,
        );
    }

    /// Establish a connection with one complete typed HTTP/3 request in the
    /// QUIC 0-RTT flight. The returned disposition is explicit so applications
    /// decide whether a rejected request is safe to replay under 1-RTT.
    pub fn connectWithEarlyRequest(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
    ) Error!EarlyHandshakeClient {
        return connectWithEarlyRequestBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            early_request,
            cache,
            lease,
            try connectDeadline(io, options.connect_timeout),
        );
    }

    pub fn connectWithEarlyRequestWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: std.Io.Clock.Timestamp,
    ) Error!EarlyHandshakeClient {
        return connectWithEarlyRequestBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            early_request,
            cache,
            lease,
            try cappedConnectDeadline(
                io,
                deadline,
                options.connect_timeout,
            ),
        );
    }

    pub fn connectWithEarlyRequestWithTimeout(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        timeout: std.Io.Duration,
    ) Error!EarlyHandshakeClient {
        if (timeout.nanoseconds <= 0) return error.HandshakeTimeout;
        return connectWithEarlyRequestWithDeadline(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            early_request,
            cache,
            lease,
            .fromNow(io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    fn connectWithEarlyRequestBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!EarlyHandshakeClient {
        if (options.handshake.early_data != null) {
            return error.InvalidEarlyDataLease;
        }
        if (options.session.max_concurrent_request_streams == 0) {
            return error.ExcessiveLoad;
        }
        if (!std.meta.eql(
            early_request.local_settings,
            options.session.local_settings,
        )) {
            return error.InvalidSetting;
        }
        try early_request.validateTransportLimits(limits, options, lease);
        var early_options = options;
        early_options.handshake.early_data = early_request.offer(cache, lease);
        var client = try connectBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            early_options,
            deadline,
            early_request,
        );
        errdefer client.deinit();
        const disposition = try client.adoptEarlyRequest(
            early_request,
        );
        if (options.handshake.resumption_server_id) |server_id| {
            if (options.handshake.resumption_now_ms) |now_ms| {
                try client.configureSessionTicketCache(
                    cache,
                    server_id,
                    now_ms,
                );
            }
        }
        return .{ .client = client, .disposition = disposition };
    }

    /// Send one complete request in 0-RTT when possible and return its final
    /// result. RFC 8470 retries a TLS-rejected early request or a 425
    /// response exactly once after the handshake, never in early data.
    pub fn requestWithEarlyData(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        request_options: http3.Request,
        early_options: PreparedEarlyRequestOptions,
        remembered_peer_settings: http3.Settings,
        limits: Limits,
        options: HandshakeClientOptions,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
    ) Error!EarlyDataRequestResult {
        return requestWithEarlyDataBefore(
            allocator,
            io,
            local_address,
            server,
            request_options,
            early_options,
            remembered_peer_settings,
            limits,
            options,
            cache,
            lease,
            null,
        ) catch |err| switch (err) {
            error.Timeout, error.ConcurrencyUnavailable => unreachable,
            else => |other| return @errorCast(other),
        };
    }

    pub fn requestWithEarlyDataWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        request_options: http3.Request,
        early_options: PreparedEarlyRequestOptions,
        remembered_peer_settings: http3.Settings,
        limits: Limits,
        options: HandshakeClientOptions,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!EarlyDataRequestResult {
        return requestWithEarlyDataBefore(
            allocator,
            io,
            local_address,
            server,
            request_options,
            early_options,
            remembered_peer_settings,
            limits,
            options,
            cache,
            lease,
            deadline,
        );
    }

    pub fn requestWithEarlyDataWithTimeout(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        request_options: http3.Request,
        early_options: PreparedEarlyRequestOptions,
        remembered_peer_settings: http3.Settings,
        limits: Limits,
        options: HandshakeClientOptions,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        timeout: std.Io.Duration,
    ) ReceiveTimeoutError!EarlyDataRequestResult {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return requestWithEarlyDataWithDeadline(
            allocator,
            io,
            local_address,
            server,
            request_options,
            early_options,
            remembered_peer_settings,
            limits,
            options,
            cache,
            lease,
            .fromNow(io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    fn requestWithEarlyDataBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        request_options: http3.Request,
        early_options: PreparedEarlyRequestOptions,
        remembered_peer_settings: http3.Settings,
        limits: Limits,
        options: HandshakeClientOptions,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: ?std.Io.Clock.Timestamp,
    ) ReceiveTimeoutError!EarlyDataRequestResult {
        const operation_deadline = if (deadline) |absolute|
            try deadline_policy.usableAwake(io, absolute)
        else
            null;
        var early_request = try PreparedEarlyRequest.initWithOptions(
            allocator,
            request_options,
            options.session.local_settings,
            remembered_peer_settings,
            early_options,
        );
        defer early_request.deinit();
        const handshake_deadline = if (operation_deadline) |absolute|
            try cappedConnectDeadline(
                io,
                absolute,
                options.connect_timeout,
            )
        else
            try connectDeadline(io, options.connect_timeout);
        const connected = try connectWithEarlyRequestBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            &early_request,
            cache,
            lease,
            handshake_deadline,
        );
        var client = connected.client;
        defer client.deinit();

        if (connected.disposition == .accepted) {
            var response = if (operation_deadline) |absolute|
                try client.receiveResponseWithDeadline(
                    early_request.stream_id,
                    absolute,
                )
            else
                try client.receiveResponse(early_request.stream_id);
            if (response.response.status != 425) {
                return .{
                    .response = response,
                    .disposition = .accepted,
                    .retry_reason = .none,
                };
            }
            response.deinit(allocator);
        }

        const response = if (operation_deadline) |absolute|
            try client.requestWithDeadline(request_options, absolute)
        else
            try client.request(request_options);
        return .{
            .response = response,
            .disposition = connected.disposition,
            .retry_reason = if (connected.disposition == .accepted)
                .too_early
            else
                .early_data_rejected,
        };
    }

    pub fn connectWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        return connectBefore(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            try cappedConnectDeadline(
                io,
                deadline,
                options.connect_timeout,
            ),
            null,
        );
    }

    pub fn connectWithTimeout(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        timeout: std.Io.Duration,
    ) Error!HandshakeClient {
        if (timeout.nanoseconds <= 0) return error.HandshakeTimeout;
        return connectWithDeadline(
            allocator,
            io,
            local_address,
            server,
            limits,
            options,
            .fromNow(io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    fn connectBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        accepted_early_request: ?*const PreparedEarlyRequest,
    ) Error!HandshakeClient {
        try validateHandshakeSessionOptions(options.session);
        const endpoint = try allocator.create(quic.runtime.Endpoint);
        errdefer allocator.destroy(endpoint);
        endpoint.* = try quic.runtime.Endpoint.bind(allocator, io, local_address, limits.quic);
        errdefer endpoint.deinit();

        var established = if (deadline) |absolute|
            try quic.handshake.connectWithDeadline(
                endpoint,
                server,
                options.handshake,
                absolute,
            )
        else
            try quic.handshake.connect(endpoint, server, options.handshake);
        errdefer established.deinit();
        var client = try initOwnedEstablished(
            allocator,
            endpoint,
            server,
            established,
            options.session,
            accepted_early_request,
        );
        errdefer client.deinit();
        if (options.handshake.auto_resumption) |automatic| {
            try client.configureSessionTicketCache(
                automatic.cache,
                automatic.server_id,
                automatic.now_ms,
            );
        }
        return client;
    }

    /// Complete QUIC/TLS on a caller-owned endpoint while consuming only the
    /// supplied datagram source. This is the handshake counterpart to
    /// `initEstablished`: an endpoint-wide receive owner can route the
    /// client's long-header packets into a bounded inbox, then register the
    /// returned 1-RTT connection without transferring endpoint ownership.
    pub fn connectFrom(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
    ) Error!HandshakeClient {
        return connectFromBefore(
            endpoint,
            source,
            server,
            options,
            try connectDeadline(endpoint.io, options.connect_timeout),
        );
    }

    pub fn connectFromWithDeadline(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        return connectFromBefore(
            endpoint,
            source,
            server,
            options,
            try cappedConnectDeadline(
                endpoint.io,
                deadline,
                options.connect_timeout,
            ),
        );
    }

    pub fn connectFromWithTimeout(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        timeout: std.Io.Duration,
    ) Error!HandshakeClient {
        if (timeout.nanoseconds <= 0) return error.HandshakeTimeout;
        return connectFromWithDeadline(
            endpoint,
            source,
            server,
            options,
            .fromNow(
                endpoint.io,
                .{ .raw = timeout, .clock = .awake },
            ),
        );
    }

    /// Move a preconfigured endpoint into a new authenticated HTTP/3 client.
    /// This is the owning composition point for transports such as SOCKS5 UDP
    /// ASSOCIATE that must construct the socket before QUIC/TLS starts.
    /// `endpoint_value` becomes invalid only after ownership transfers.
    pub fn connectAdoptingEndpoint(
        allocator: std.mem.Allocator,
        endpoint_value: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
    ) Error!HandshakeClient {
        return connectAdoptingEndpointBefore(
            allocator,
            endpoint_value,
            server,
            options,
            try connectDeadline(endpoint_value.io, options.connect_timeout),
        );
    }

    pub fn connectAdoptingEndpointWithDeadline(
        allocator: std.mem.Allocator,
        endpoint_value: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        return connectAdoptingEndpointBefore(
            allocator,
            endpoint_value,
            server,
            options,
            try cappedConnectDeadline(
                endpoint_value.io,
                deadline,
                options.connect_timeout,
            ),
        );
    }

    fn connectAdoptingEndpointBefore(
        allocator: std.mem.Allocator,
        endpoint_value: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        const endpoint = try allocator.create(quic.runtime.Endpoint);
        endpoint.* = endpoint_value.*;
        endpoint_value.* = undefined;
        return connectOwningEndpointBefore(
            endpoint,
            server,
            options,
            deadline,
        );
    }

    /// Take ownership of an allocator-created endpoint pointer immediately.
    /// On failure this function closes and destroys it; on success ownership
    /// moves into the returned client.
    pub fn connectOwningEndpoint(
        endpoint: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
    ) Error!HandshakeClient {
        return connectOwningEndpointBefore(
            endpoint,
            server,
            options,
            try connectDeadline(endpoint.io, options.connect_timeout),
        );
    }

    pub fn connectOwningEndpointWithDeadline(
        endpoint: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        return connectOwningEndpointBefore(
            endpoint,
            server,
            options,
            try cappedConnectDeadline(
                endpoint.io,
                deadline,
                options.connect_timeout,
            ),
        );
    }

    fn connectOwningEndpointBefore(
        endpoint: *quic.runtime.Endpoint,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        const allocator = endpoint.allocator;
        errdefer {
            endpoint.deinit();
            allocator.destroy(endpoint);
        }
        try validateHandshakeSessionOptions(options.session);
        var connect_options = options;
        connect_options.connect_timeout = null;
        var established = if (deadline) |absolute|
            try quic.handshake.connectWithDeadline(
                endpoint,
                server,
                connect_options.handshake,
                absolute,
            )
        else
            try quic.handshake.connect(
                endpoint,
                server,
                connect_options.handshake,
            );
        errdefer established.deinit();
        var client = try initOwnedEstablished(
            allocator,
            endpoint,
            server,
            established,
            connect_options.session,
            null,
        );
        errdefer client.deinit();
        if (connect_options.handshake.auto_resumption) |automatic| {
            try client.configureSessionTicketCache(
                automatic.cache,
                automatic.server_id,
                automatic.now_ms,
            );
        }
        return client;
    }

    /// Complete a typed 0-RTT handshake on a caller-owned endpoint while
    /// consuming only the supplied CID-routed datagram source.
    pub fn connectFromWithEarlyRequest(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
    ) Error!EarlyHandshakeClient {
        return connectFromWithEarlyRequestBefore(
            endpoint,
            source,
            server,
            options,
            early_request,
            cache,
            lease,
            try connectDeadline(endpoint.io, options.connect_timeout),
        );
    }

    pub fn connectFromWithEarlyRequestWithDeadline(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: std.Io.Clock.Timestamp,
    ) Error!EarlyHandshakeClient {
        return connectFromWithEarlyRequestBefore(
            endpoint,
            source,
            server,
            options,
            early_request,
            cache,
            lease,
            try cappedConnectDeadline(
                endpoint.io,
                deadline,
                options.connect_timeout,
            ),
        );
    }

    fn connectFromWithEarlyRequestBefore(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!EarlyHandshakeClient {
        if (options.handshake.early_data != null) {
            return error.InvalidEarlyDataLease;
        }
        if (options.session.max_concurrent_request_streams == 0) {
            return error.ExcessiveLoad;
        }
        if (!std.meta.eql(
            early_request.local_settings,
            options.session.local_settings,
        )) {
            return error.InvalidSetting;
        }
        try early_request.validateTransportLimits(
            .{ .quic = endpoint.limits },
            options,
            lease,
        );
        var early_options = options;
        early_options.handshake.early_data = early_request.offer(cache, lease);
        var client = try connectFromBeforeInternal(
            endpoint,
            source,
            server,
            early_options,
            deadline,
            early_request,
        );
        errdefer client.deinit();
        const disposition = try client.adoptEarlyRequest(early_request);
        if (options.handshake.resumption_server_id) |server_id| {
            if (options.handshake.resumption_now_ms) |now_ms| {
                try client.configureSessionTicketCache(
                    cache,
                    server_id,
                    now_ms,
                );
            }
        }
        return .{ .client = client, .disposition = disposition };
    }

    fn connectFromBefore(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        return connectFromBeforeInternal(
            endpoint,
            source,
            server,
            options,
            deadline,
            null,
        );
    }

    fn connectFromBeforeInternal(
        endpoint: *quic.runtime.Endpoint,
        source: quic.runtime.DatagramSource,
        server: net.IpAddress,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        accepted_early_request: ?*const PreparedEarlyRequest,
    ) Error!HandshakeClient {
        try validateHandshakeSessionOptions(options.session);
        var established = if (deadline) |absolute|
            try quic.handshake.connectFromWithDeadline(
                endpoint,
                source,
                server,
                options.handshake,
                absolute,
            )
        else
            try quic.handshake.connectFrom(
                endpoint,
                source,
                server,
                options.handshake,
            );
        errdefer established.deinit();
        var client = try initEstablishedWithEndpointOwnership(
            endpoint.allocator,
            endpoint,
            false,
            server,
            established,
            options.session,
            accepted_early_request,
        );
        errdefer client.deinit();
        if (options.handshake.auto_resumption) |automatic| {
            try client.configureSessionTicketCache(
                automatic.cache,
                automatic.server_id,
                automatic.now_ms,
            );
        }
        return client;
    }

    /// Build an HTTP/3 client around an established connection on a
    /// caller-owned endpoint. This is the client-side composition point for
    /// endpoint-wide dispatchers that multiplex several connections over one
    /// UDP socket. Ownership of `established` transfers on success; `endpoint`
    /// remains caller-owned and must outlive this client.
    pub fn initEstablished(
        endpoint: *quic.runtime.Endpoint,
        peer: net.IpAddress,
        established: quic.handshake.EstablishedConnection,
        options: HandshakeSessionOptions,
    ) Error!HandshakeClient {
        try validateHandshakeSessionOptions(options);
        if (established.connection.endpoint != endpoint) {
            return error.InvalidTransportParameter;
        }
        return initEstablishedWithEndpointOwnership(
            endpoint.allocator,
            endpoint,
            false,
            peer,
            established,
            options,
            null,
        );
    }

    /// Build the HTTP/3 client state around a successfully initialized QUIC
    /// connection. Ownership of both `endpoint` and `established` transfers
    /// only on success. Keeping this common path prevents the TLS and external
    /// key-negotiation entry points from drifting in lifecycle behavior.
    fn initOwnedEstablished(
        allocator: std.mem.Allocator,
        endpoint: *quic.runtime.Endpoint,
        peer: net.IpAddress,
        established: quic.handshake.EstablishedConnection,
        options: HandshakeSessionOptions,
        accepted_early_request: ?*const PreparedEarlyRequest,
    ) Error!HandshakeClient {
        return initEstablishedWithEndpointOwnership(
            allocator,
            endpoint,
            true,
            peer,
            established,
            options,
            accepted_early_request,
        );
    }

    fn initEstablishedWithEndpointOwnership(
        allocator: std.mem.Allocator,
        endpoint: *quic.runtime.Endpoint,
        owns_endpoint: bool,
        peer: net.IpAddress,
        established: quic.handshake.EstablishedConnection,
        options: HandshakeSessionOptions,
        accepted_early_request: ?*const PreparedEarlyRequest,
    ) Error!HandshakeClient {
        const resolved_options = resolvePacedBodyChunkBytes(
            options,
            default_paced_request_body_chunk_bytes,
        );
        try validateHandshakeSessionOptions(resolved_options);
        if (!http3.isHttp3Alpn(established.alpn)) return error.InvalidAlpn;
        const max_capacity = std.math.cast(
            usize,
            resolved_options.local_settings.qpack_max_table_capacity,
        ) orelse return error.InvalidSetting;
        const transport_next_stream_id = std.math.cast(
            u62,
            established.connection.nextLocalBidirectionalStreamId(),
        ) orelse return error.StreamCreationError;
        const typed_early_data = established.early_data_status == .accepted and
            established.early_data_sent_packet_count != 0 and
            accepted_early_request != null;
        const expected_bidi_stream_id: u62 = if (typed_early_data) 4 else 0;
        if (transport_next_stream_id != expected_bidi_stream_id) {
            return error.UnexpectedEarlyData;
        }
        const transport_next_uni_stream_id =
            established.connection.nextLocalUnidirectionalStreamId();
        const expected_uni_stream_id: u64 = if (typed_early_data)
            first_client_extension_uni_stream_id
        else
            client_control_stream_id;
        if (transport_next_uni_stream_id != expected_uni_stream_id) {
            // Accepted typed early data reserves exactly the three mandatory
            // HTTP/3 critical streams. Other preexisting unidirectional state
            // cannot be reconstructed safely by this fresh session.
            return error.StreamCreationError;
        }
        var client = HandshakeClient{
            .endpoint = endpoint,
            .owns_endpoint = owns_endpoint,
            .peer = peer,
            .allocator = allocator,
            .established = established,
            .options = resolved_options,
            .control = try .init(.{
                .max_priority_updates = resolved_options.max_priority_updates,
                .max_priority_update_payload_size = resolved_options.max_priority_update_payload_size,
            }),
            .qpack_decode = .init(
                allocator,
                max_capacity,
                resolved_options.max_stream_buffer,
            ),
            .qpack_encode = .initAwaitingPeerSettings(
                allocator,
                resolved_options.max_stream_buffer,
            ),
            .response_streams = .init(
                allocator,
                resolved_options.max_stream_buffer,
                resolved_options.max_concurrent_request_streams,
            ),
            .streaming_responses = .initWithInformationalLimit(
                allocator,
                resolved_options.max_concurrent_request_streams,
                resolved_options.max_stream_buffer,
                resolved_options.max_informational_responses,
                resolved_options.local_settings,
                .response,
            ),
            .push_streams = .initWithInformationalLimit(
                allocator,
                resolved_options.max_concurrent_request_streams,
                resolved_options.max_stream_buffer,
                resolved_options.max_informational_responses,
                resolved_options.local_settings,
            ),
            .receive_packets = .{
                .max_datagrams = resolved_options.max_receive_batch_datagrams,
            },
            .request_lifecycle = .init(
                allocator,
                resolved_options.max_concurrent_request_streams,
            ),
            .connect_datagrams = .init(allocator, .{
                .max_associations = resolved_options.max_concurrent_request_streams,
                .max_queued_per_association = resolved_options.max_queued_connect_datagrams,
                .max_queued_bytes_per_association = resolved_options.max_queued_connect_datagram_bytes,
            }),
            .outbound_bodies = .init(
                allocator,
                resolved_options.max_concurrent_request_streams,
            ),
            .ticket_receiver = .init(
                allocator,
                resolved_options.max_post_handshake_crypto_bytes,
            ),
            .next_stream_id = transport_next_stream_id,
        };
        if (transport_next_stream_id != 0) {
            client.request_lifecycle.markAllocated(
                transport_next_stream_id - 4,
            );
        }
        return client;
    }

    pub fn initPreconfigured(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        peer: net.IpAddress,
        limits: Limits,
        options: HandshakeSessionOptions,
        transport: quic.handshake.PreconfiguredConnectionOptions,
    ) Error!HandshakeClient {
        try validateHandshakeSessionOptions(options);
        const endpoint = try allocator.create(quic.runtime.Endpoint);
        errdefer allocator.destroy(endpoint);
        endpoint.* = try quic.runtime.Endpoint.bind(
            allocator,
            io,
            local_address,
            limits.quic,
        );
        errdefer endpoint.deinit();
        var established = try quic.handshake.establishPreconfigured(
            endpoint,
            peer,
            .client,
            transport,
        );
        errdefer established.deinit();
        return initOwnedEstablished(
            allocator,
            endpoint,
            peer,
            established,
            options,
            null,
        );
    }

    const ResolvedEarlyConnect = struct {
        request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
    };

    const ResolvedConnectResult = struct {
        client: HandshakeClient,
        disposition: ?EarlyRequestDisposition = null,
    };

    /// Try every reachable DNS result under the configured ordered or
    /// RFC 8305-style staggered policy. Protocol/authentication failures remain
    /// fatal across the origin, while path failures can advance another route.
    fn connectAnyResolvedAddress(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        servers: []const net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!HandshakeClient {
        const connected = try connectAnyResolvedAddressInternal(
            allocator,
            io,
            local_address,
            servers,
            limits,
            options,
            deadline,
            null,
        );
        std.debug.assert(connected.disposition == null);
        return connected.client;
    }

    fn connectAnyResolvedAddressWithEarlyRequest(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        servers: []const net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        early_request: *const PreparedEarlyRequest,
        cache: *quic.resumption.Cache,
        lease: *quic.resumption.EarlyDataLease,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!EarlyHandshakeClient {
        const connected = try connectAnyResolvedAddressInternal(
            allocator,
            io,
            local_address,
            servers,
            limits,
            options,
            deadline,
            .{ .request = early_request, .cache = cache, .lease = lease },
        );
        return .{
            .client = connected.client,
            .disposition = connected.disposition orelse unreachable,
        };
    }

    fn connectAnyResolvedAddressInternal(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        servers: []const net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        early: ?ResolvedEarlyConnect,
    ) Error!ResolvedConnectResult {
        if (servers.len == 0) return error.NoAddressReturned;
        try validateResolvedAddressPolicy(local_address, options);
        return switch (options.address_connect_policy) {
            .ordered => connectResolvedAddressesOrdered(
                allocator,
                io,
                local_address,
                servers,
                limits,
                options,
                deadline,
                early,
            ),
            .happy_eyeballs => |policy| connectResolvedAddressesRacing(
                allocator,
                io,
                local_address,
                servers,
                limits,
                options,
                deadline,
                early,
                policy,
            ),
        };
    }

    fn connectResolvedAddressesOrdered(
        allocator: std.mem.Allocator,
        io: std.Io,
        primary_local_address: net.IpAddress,
        servers: []const net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        early: ?ResolvedEarlyConnect,
    ) Error!ResolvedConnectResult {
        var attempted = false;
        var attempt_index: usize = 0;
        var early_path_failed = false;
        var last_err: ?Error = null;
        for (servers) |server| {
            const local_address = localAddressForResolvedPeer(
                primary_local_address,
                options.alternate_local_address,
                server,
            ) orelse continue;
            attempted = true;
            const attempt_early = if (!early_path_failed) early else null;
            return connectResolvedAddressAttempt(
                allocator,
                io,
                local_address,
                server,
                limits,
                options,
                deadline,
                attempt_early,
                early != null and attempt_early == null,
                attempt_index != 0,
            ) catch |err| {
                last_err = err;
                if (!shouldTryNextResolvedAddress(err)) return err;
                if (attempt_early != null) early_path_failed = true;
                attempt_index += 1;
                continue;
            };
        }
        if (!attempted) return error.AddressFamilyUnsupported;
        return last_err orelse error.NoAddressReturned;
    }

    fn connectResolvedAddressesRacing(
        allocator: std.mem.Allocator,
        io: std.Io,
        primary_local_address: net.IpAddress,
        servers: []const net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        early: ?ResolvedEarlyConnect,
        policy: HappyEyeballsOptions,
    ) Error!ResolvedConnectResult {
        try happy_eyeballs.validate(policy);
        const stack_address_capacity: usize = 8;
        var eligible_count: usize = 0;
        for (servers) |server| {
            if (localAddressForResolvedPeer(
                primary_local_address,
                options.alternate_local_address,
                server,
            ) != null) eligible_count += 1;
        }
        if (eligible_count == 0) return error.AddressFamilyUnsupported;

        var eligible_stack: [stack_address_capacity]net.IpAddress = undefined;
        const eligible_heap = if (eligible_count > eligible_stack.len)
            try allocator.alloc(net.IpAddress, eligible_count)
        else
            null;
        defer if (eligible_heap) |storage| allocator.free(storage);
        const eligible = eligible_heap orelse eligible_stack[0..eligible_count];
        var eligible_index: usize = 0;
        for (servers) |server| {
            if (localAddressForResolvedPeer(
                primary_local_address,
                options.alternate_local_address,
                server,
            ) == null) continue;
            eligible[eligible_index] = server;
            eligible_index += 1;
        }

        const RaceContext = struct {
            allocator: std.mem.Allocator,
            primary_local_address: net.IpAddress,
            limits: Limits,
            options: HandshakeClientOptions,
            deadline: ?std.Io.Clock.Timestamp,
            early: ?ResolvedEarlyConnect,

            fn connect(
                self: @This(),
                io_value: std.Io,
                server: net.IpAddress,
                index: usize,
            ) Error!ResolvedConnectResult {
                return connectResolvedAddressAttempt(
                    self.allocator,
                    io_value,
                    localAddressForResolvedPeer(
                        self.primary_local_address,
                        self.options.alternate_local_address,
                        server,
                    ).?,
                    server,
                    self.limits,
                    self.options,
                    self.deadline,
                    if (index == 0) self.early else null,
                    self.early != null and index != 0,
                    index != 0,
                );
            }

            fn deinitConnected(
                _: @This(),
                connected: *ResolvedConnectResult,
            ) void {
                connected.client.deinit();
            }
        };
        return happy_eyeballs.race(
            Error,
            ResolvedConnectResult,
            allocator,
            io,
            eligible,
            policy,
            null,
            null,
            RaceContext{
                .allocator = allocator,
                .primary_local_address = primary_local_address,
                .limits = limits,
                .options = options,
                .deadline = deadline,
                .early = early,
            },
            RaceContext.connect,
            RaceContext.deinitConnected,
            shouldTryNextResolvedAddress,
        );
    }

    fn connectResolvedAddressAttempt(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        server: net.IpAddress,
        limits: Limits,
        options: HandshakeClientOptions,
        deadline: ?std.Io.Clock.Timestamp,
        early: ?ResolvedEarlyConnect,
        fallback_from_early: bool,
        fresh_identity: bool,
    ) Error!ResolvedConnectResult {
        var attempt_options = options;
        var original_dcid: [8]u8 = undefined;
        var local_cid: [8]u8 = undefined;
        if (fresh_identity) {
            try std.Io.randomSecure(io, &original_dcid);
            try std.Io.randomSecure(io, &local_cid);
            attempt_options.handshake.original_destination_connection_id =
                &original_dcid;
            attempt_options.handshake.local_connection_id = &local_cid;
            attempt_options.handshake.retry_source_connection_id = &.{};
            attempt_options.handshake.address_validation_token = &.{};
            attempt_options.handshake.resumption_session = null;
            attempt_options.handshake.resumption_server_id = null;
            attempt_options.handshake.auto_resumption = null;
            attempt_options.handshake.random = null;
            attempt_options.handshake.x25519_secret_key = null;
            attempt_options.handshake.p256_secret_key = null;
            attempt_options.handshake.p384_secret_key = null;
            attempt_options.handshake.x25519_mlkem768_secret_key = null;
            attempt_options.handshake.x25519_mlkem768_seed = null;
            attempt_options.handshake.nist_hybrid_key_material = .{};
            attempt_options.handshake.early_data = null;
        }
        const attempt_deadline = try addressAttemptDeadline(
            io,
            deadline,
            options.address_attempt_timeout,
        );
        if (attempt_deadline) |absolute| {
            attempt_options.handshake.handshake_recovery =
                try handshakeRecoveryBefore(
                    io,
                    absolute,
                    options.handshake.handshake_recovery,
                );
        }
        if (early) |early_context| {
            const connected = try connectWithEarlyRequestBefore(
                allocator,
                io,
                local_address,
                server,
                limits,
                attempt_options,
                early_context.request,
                early_context.cache,
                early_context.lease,
                attempt_deadline,
            );
            return .{
                .client = connected.client,
                .disposition = connected.disposition,
            };
        }
        return .{
            .client = try connect(
                allocator,
                io,
                local_address,
                server,
                limits,
                attempt_options,
            ),
            .disposition = if (fallback_from_early) .rejected else null,
        };
    }

    fn validateResolvedAddressPolicy(
        primary_local_address: net.IpAddress,
        options: HandshakeClientOptions,
    ) Error!void {
        switch (options.address_connect_policy) {
            .ordered => {},
            .happy_eyeballs => |policy| try happy_eyeballs.validate(policy),
        }
        if (options.alternate_local_address) |alternate| {
            if (sameIpAddressFamily(primary_local_address, alternate)) {
                return error.InvalidAddressConnectPolicy;
            }
        }
    }

    fn localAddressForResolvedPeer(
        primary: net.IpAddress,
        alternate: ?net.IpAddress,
        peer: net.IpAddress,
    ) ?net.IpAddress {
        if (sameIpAddressFamily(primary, peer)) return primary;
        if (alternate) |candidate| {
            if (sameIpAddressFamily(candidate, peer)) return candidate;
        }
        return null;
    }

    fn sameIpAddressFamily(a: net.IpAddress, b: net.IpAddress) bool {
        return switch (a) {
            .ip4 => switch (b) {
                .ip4 => true,
                .ip6 => false,
            },
            .ip6 => switch (b) {
                .ip4 => false,
                .ip6 => true,
            },
        };
    }

    fn shouldTryNextResolvedAddress(err: Error) bool {
        return switch (err) {
            error.HandshakeTimeout,
            error.HandshakeSendFailed,
            error.HandshakeReceiveFailed,
            error.AddressFamilyUnsupported,
            error.ConnectionRefused,
            error.ConnectionResetByPeer,
            error.HostUnreachable,
            error.NetworkDown,
            error.NetworkUnreachable,
            error.PortUnreachable,
            => true,
            else => false,
        };
    }

    pub fn connectUri(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        uri: std.Uri,
        limits: Limits,
        options: HandshakeClientOptions,
    ) Error!HandshakeClient {
        return connectUriBefore(
            allocator,
            io,
            local_address,
            uri,
            limits,
            options,
            try connectDeadline(io, options.connect_timeout),
        );
    }

    pub fn connectUriWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        local_address: net.IpAddress,
        uri: std.Uri,
